1	import 'package:flutter_secure_storage/flutter_secure_storage.dart';
2	
3	/// The port [HeaderInterceptor] reads the current user's access token
4	/// through. Owned by `core/` (not a feature) since the header-policy rule
5	/// (AD-5) is core infrastructure; the `auth` feature calls
6	/// [saveAccessToken]/[clearAccessToken] on login/logout (Story 1.3) and
7	/// [saveSession]/[readRefreshToken]/[clearSession] for refresh-token
8	/// persistence (Story 1.4) without this contract's existing three methods
9	/// changing.
10	abstract class AccessTokenProvider {
11	  Future<String?> readAccessToken();
12	
13	  Future<void> saveAccessToken(String token);
14	
15	  Future<void> clearAccessToken();
16	
17	  /// Reads the refresh token persisted by [saveSession], or `null` if none
18	  /// is stored (fresh install / post-logout / post-clear).
19	  Future<String?> readRefreshToken();
20	
21	  /// Persists both halves of a session pair in one call — used after
22	  /// signup/login/refresh so the access and refresh tokens are never saved
23	  /// out of step with each other.
24	  Future<void> saveSession({
25	    required String accessToken,
26	    required String refreshToken,
27	  });
28	
29	  /// Clears both the access and refresh tokens — used when the backend
30	  /// reports the stored refresh token is dead (`AUTH_EXPIRED`/`AUTH_INVALID`).
31	  Future<void> clearSession();
32	}
33	
34	/// Default implementation, backed by `flutter_secure_storage` — the same
35	/// package this story's DI bootstrap integration test proves works end to
36	/// end through `get_it`.
37	class SecureStorageAccessTokenProvider implements AccessTokenProvider {
38	  SecureStorageAccessTokenProvider(this._storage);
39	
40	  static const _key = 'user_access_token';
41	
42	  /// New key, alongside [_key], for the refresh token (Story 1.4).
43	  static const _refreshKey = 'user_refresh_token';
44	
45	  final FlutterSecureStorage _storage;
46	
47	  @override
48	  Future<String?> readAccessToken() => _storage.read(key: _key);
49	
50	  @override
51	  Future<void> saveAccessToken(String token) =>
52	      _storage.write(key: _key, value: token);
53	
54	  @override
55	  Future<void> clearAccessToken() => _storage.delete(key: _key);
56	
57	  @override
58	  Future<String?> readRefreshToken() => _storage.read(key: _refreshKey);
59	
60	  @override
61	  Future<void> saveSession({
62	    required String accessToken,
63	    required String refreshToken,
64	  }) async {
65	    // Refresh token first: these are two independent sequential writes
66	    // (no atomic multi-key transaction in `flutter_secure_storage`), so if
67	    // the second write below ever fails, this order leaves the *refresh*
68	    // token as the backend's latest-issued one — the next boot's
69	    // `restoreSession()` self-heals from it rather than replaying a
70	    // possibly-already-rotated-away one. The access token staying stale in
71	    // that failure case is the lesser problem: it only affects calls made
72	    // before the next boot.
73	    await _storage.write(key: _refreshKey, value: refreshToken);
74	    await _storage.write(key: _key, value: accessToken);
75	  }
76	
77	  @override
78	  Future<void> clearSession() async {
79	    // Refresh token first (mirrors `saveSession`'s ordering rationale):
80	    // it's the one `restoreSession()` reads to decide whether to call
81	    // `auth-refresh` at all, so clearing it first guarantees a
82	    // backend-confirmed-dead token is never retried even if the
83	    // access-token delete below then fails.
84	    await _storage.delete(key: _refreshKey);
85	    await _storage.delete(key: _key);
86	  }
87	}
