13	
14	/// Same tiny fake used by `app_router_test.dart`/`main_test.dart` — gives
15	/// synchronous control over both [SessionStatus] values and the
16	/// [statusStream] emission `ExpiryOverlayHost` subscribes to.
17	class _FakeSessionRepository implements SessionRepository {
18	  SessionStatus? _status;
19	  final _controller = StreamController<SessionStatus>.broadcast();
20	
21	  @override
22	  SessionStatus? get currentStatus => _status;
23	
24	  @override
25	  Stream<SessionStatus> get statusStream => _controller.stream;
26	
27	  @override
28	  Future<Either<Failure, Unit>> restoreSession() async => right(unit);
29	
30	  @override
31	  void markAuthenticated() => setStatus(SessionStatus.authenticated);
32	
33	  // Story 8.4 — not exercised by this overlay-focused suite, same trivial
34	  // rationale this fake's other untouched members already follow.
35	  @override
36	  Future<Either<Failure, Unit>> logout() async => right(unit);
37	
38	  @override
39	  Future<void> dispose() => _controller.close();
40	
41	  void setStatus(SessionStatus status) {
42	    _status = status;
43	    _controller.add(status);
44	  }
45	}
46	
47	void main() {
48	  setUp(() {
49	    ConfirmationDialog.isOpen = false;
50	  });
51	
52	  testWidgets('an expired emission before the Navigator behind navigatorKey is '
53	      'mounted finds no overlay context, does not throw, and resets its '
54	      'one-shot guard so a later mount can still show the overlay', (
55	    tester,
56	  ) async {
57	    final fakeSessionRepository = _FakeSessionRepository();
58	    addTearDown(fakeSessionRepository.dispose);
59	    final router = GoRouter(
60	      routes: [
61	        GoRoute(path: '/', builder: (context, state) => const SizedBox()),
62	      ],
63	    );
64	    addTearDown(router.dispose);
65	    final navigatorKey = GlobalKey<NavigatorState>();
66	
67	    // First mount: `navigatorKey` matches nothing in this tree — no
68	    // `Navigator` anywhere uses it — simulating the Navigator not being
69	    // mounted yet when the expiry event arrives.
70	    await tester.pumpWidget(
71	      Directionality(
72	        textDirection: TextDirection.ltr,
73	        child: ExpiryOverlayHost(
74	          sessionRepository: fakeSessionRepository,
75	          router: router,
76	          navigatorKey: navigatorKey,
77	          child: const SizedBox(),
78	        ),
79	      ),
80	    );
81	
82	    fakeSessionRepository.setStatus(SessionStatus.expired);
83	    await tester.pumpAndSettle();
84	
85	    expect(tester.takeException(), isNull);
86	    expect(find.byType(ConfirmationDialog), findsNothing);
87	
88	    // Second pump of the *same* `ExpiryOverlayHost` (same type, no key,
89	    // same position — its State is preserved, not remounted): now the
90	    // child actually contains a `Navigator` using `navigatorKey`, so
91	    // `navigatorKey.currentState` resolves. Re-emitting `expired` here
92	    // only shows the overlay if the earlier failed attempt reset
93	    // `_expiryOverlayShown` back to `false` — if that guard had stayed
94	    // stuck `true`, this second, now-resolvable attempt would stay
95	    // silently dropped too.
96	    await tester.pumpWidget(
97	      Directionality(
98	        textDirection: TextDirection.ltr,
99	        child: ExpiryOverlayHost(
100	          sessionRepository: fakeSessionRepository,
101	          router: router,
102	          navigatorKey: navigatorKey,
103	          child: Navigator(
104	            key: navigatorKey,
105	            onGenerateRoute: (settings) =>
106	                MaterialPageRoute<void>(builder: (context) => const SizedBox()),
107	          ),
108	        ),
109	      ),
110	    );
111	
112	    fakeSessionRepository.setStatus(SessionStatus.expired);
113	    await tester.pumpAndSettle();
114	
115	    expect(tester.takeException(), isNull);
116	    expect(find.text('Sessão expirada'), findsOneWidget);
117	  });
118	}
