6	/// RNF09 — the one shared, table-driven helper every write-endpoint test
7	/// reuses: for a given write call, stubs each of the 3 failure types
8	/// (timeout, malformed response, no connection) and asserts it resolves to
9	/// `Left<Failure>` with zero unhandled exceptions, via `mocktail`.
10	///
11	/// Callers stub their own mocked `ApiClient` (per the architecture spine's
12	/// testing convention — tests mock `ApiClient`, not a fake transport layer)
13	/// through [stubNetworkTimeout]/[stubMalformedResponse]/[stubNoConnection],
14	/// then supply [invoke] — the repository/data-source call under test, which
15	/// must itself return `Either<Failure, T>`.
16	///
17	/// The 5-write-endpoints x 3-failure-types = 15-scenario matrix (RNF09)
18	/// accumulates across stories as each write endpoint gets its own call to
19	/// this helper; this story proves the helper once against `auth-signup`.
20	void runWriteFailureMatrix<T>({
21	  required String endpointName,
22	  required void Function() stubNetworkTimeout,
23	  required void Function() stubMalformedResponse,
24	  required void Function() stubNoConnection,
25	  required Future<Either<Failure, T>> Function() invoke,
26	}) {
27	  group('$endpointName write-failure matrix (RNF09)', () {
28	    test('network timeout -> Left(Failure), no unhandled exception', () async {
29	      stubNetworkTimeout();
30	
31	      final result = await invoke();
32	
33	      expect(result.isLeft(), isTrue);
34	    });
35	
36	    test(
37	      'malformed response -> Left(Failure), no unhandled exception',
38	      () async {
39	        stubMalformedResponse();
40	
41	        final result = await invoke();
42	
43	        expect(result.isLeft(), isTrue);
44	      },
45	    );
46	
47	    test('no connection -> Left(Failure), no unhandled exception', () async {
48	      stubNoConnection();
49	
50	      final result = await invoke();
51	
52	      expect(result.isLeft(), isTrue);
53	    });
54	  });
55	}
