12	/// Stands in for a write-endpoint's repository call (none exists yet — this
13	/// story builds no feature repository, AGENTS.md's F000 boundary). It is
14	/// exactly the generic shape every later write-endpoint call will have:
15	/// call `ApiClient.post` for a function name and pass its `Either` straight
16	/// through — proving [runWriteFailureMatrix] against `auth-signup`.
17	Future<Either<Failure, Map<String, dynamic>>> _signUp(ApiClient apiClient) =>
18	    apiClient.post(
19	      'auth-signup',
20	      data: {'email': 'user@example.com', 'password': 'p4ssw0rd'},
21	    );
22	
23	void main() {
24	  late MockApiClient mockApiClient;
25	
26	  setUp(() {
27	    mockApiClient = MockApiClient();
28	  });
29	
30	  runWriteFailureMatrix<Map<String, dynamic>>(
31	    endpointName: 'auth-signup',
32	    stubNetworkTimeout: () {
33	      when(
34	        () => mockApiClient.post(any(), data: any(named: 'data')),
35	      ).thenAnswer(
36	        (_) async =>
37	            left(const Failure.networkTimeout(message: 'Request timed out')),
38	      );
39	    },
40	    stubMalformedResponse: () {
41	      when(
42	        () => mockApiClient.post(any(), data: any(named: 'data')),
43	      ).thenAnswer(
44	        (_) async => left(
45	          const Failure.malformedResponse(message: 'Could not parse response'),
46	        ),
47	      );
48	    },
