1	// The constructor keeps public named params (`remoteDataSource`,
2	// `accessTokenProvider`) distinct from the private fields they initialize,
3	// matching `api_client.dart`'s documented convention — an initializing
4	// formal isn't a clean fit here either.
5	// ignore_for_file: prefer_initializing_formals
6	import 'package:fpdart/fpdart.dart';
7	
8	import '../../../../core/failure/failure.dart';
9	import '../../../../core/network/access_token_provider.dart';
10	import '../../domain/entities/authenticated_user.dart';
11	import '../../domain/repositories/auth_repository.dart';
12	import '../datasources/auth_remote_data_source.dart';
13	import '../models/auth_response_dto.dart';
14	
15	/// Maps the DTO to the domain entity and saves both the access token and
16	/// the refresh token (Story 1.4) *before* returning `right(...)`.
17	class AuthRepositoryImpl implements AuthRepository {
18	  AuthRepositoryImpl({
19	    required AuthRemoteDataSource remoteDataSource,
20	    required AccessTokenProvider accessTokenProvider,
21	  }) : _remoteDataSource = remoteDataSource,
22	       _accessTokenProvider = accessTokenProvider;
23	
24	  final AuthRemoteDataSource _remoteDataSource;
25	  final AccessTokenProvider _accessTokenProvider;
26	
27	  @override
28	  Future<Either<Failure, AuthenticatedUser>> signUp({
29	    required String email,
30	    required String password,
31	  }) => _authenticate(
32	    () => _remoteDataSource.signUp(email: email, password: password),
33	  );
34	
35	  @override
36	  Future<Either<Failure, AuthenticatedUser>> logIn({
37	    required String email,
38	    required String password,
39	  }) => _authenticate(
40	    () => _remoteDataSource.logIn(email: email, password: password),
41	  );
42	
43	  Future<Either<Failure, AuthenticatedUser>> _authenticate(
44	    Future<Either<Failure, AuthResponseDto>> Function() call,
45	  ) async {
46	    final result = await call();
47	    return result.match((failure) async => left(failure), (dto) async {
48	      // A thrown platform exception (secure-storage channel failure, disk
49	      // issue, ...) must never escape unmapped (RNF09/AD-2) — if the token
50	      // can't be persisted, the call as a whole must surface as a Failure
51	      // rather than leave the caller awaiting forever. Deliberately reuses
52	      // `malformedResponse` (the only local-only variant in the closed,
53	      // exactly-14-subtype `Failure` hierarchy, AD-3) rather than adding a
54	      // new subtype just for this — it mislabels a local persistence
55	      // failure as a response-shape failure, but a dedicated subtype
56	      // isn't available without widening the closed hierarchy.
57	      try {
58	        await _accessTokenProvider.saveSession(
59	          accessToken: dto.data.session.accessToken,
60	          refreshToken: dto.data.session.refreshToken,
61	        );
62	      } catch (error) {
63	        return left(Failure.malformedResponse(message: error.toString()));
64	      }
65	      return right(
66	        AuthenticatedUser(id: dto.data.user.id, email: dto.data.user.email),
67	      );
68	    });
69	  }
70	}
