378	/// spec-6-5 — wraps the real `testWidgets` so every test in this file
379	/// automatically closes `sl<ChatCubit>()` right after its own body
380	/// completes (success or failure). A bootstrapped `ChatCubit` now always
381	/// starts a real `_insightInactivityTimer`; the ordinary `addTearDown`/
382	/// group-level `tearDown()` pattern this suite already uses for other
383	/// cleanup runs too late to satisfy `testWidgets`' own `!timersPending`
384	/// invariant check — that check runs *inside* the test's own callback
385	/// execution, before any `addTearDown`/`tearDown` callback ever fires.
386	/// Resolving the lazy singleton here is harmless even for a test that
387	/// never reaches `/` at all: resolving it alone never calls `init()`, so
388	/// no bootstrap/timer ever started in that case either.
389	void testWidgets(String description, WidgetTesterCallback callback) {
390	  testWidgetsWithCleanup(
391	    description,
392	    callback,
393	    cleanup: () async {
394	      // Review fix: guards `isClosed` too, not just `isRegistered` — a
395	      // double `close()` on an already-closed Cubit never resolves
396	      // inside flutter_test's fake-async zone, freezing the suite (the
397	      // exact hazard `app_drawer_test.dart`'s/`main_test.dart`'s own
398	      // tearDown already guards against).
399	      if (sl.isRegistered<ChatCubit>() && !sl<ChatCubit>().isClosed) {
400	        await sl<ChatCubit>().close();
401	      }
402	    },
403	  );
