class MockAuthRepository extends Mock implements AuthRepository {}

class MockSessionRepository extends Mock implements SessionRepository {}

/// A plain (non-mocktail) fake — the redirect matrix needs [currentStatus]
/// read synchronously right after [setStatus], and `statusStream` to
/// actually emit so `GoRouterRefreshStream` re-triggers `redirect`; a
/// mocktail stub can't do both at once as naturally as this tiny fake.
class _FakeSessionRepository implements SessionRepository {
  SessionStatus? _status;
  final _controller = StreamController<SessionStatus>.broadcast();

  @override
  SessionStatus? get currentStatus => _status;

  @override
  Stream<SessionStatus> get statusStream => _controller.stream;

  @override
  Future<Either<Failure, Unit>> restoreSession() async => right(unit);

  @override
  void markAuthenticated() => setStatus(SessionStatus.authenticated);

  @override
  Future<void> dispose() => _controller.close();

  void setStatus(SessionStatus status) {
    _status = status;
    _controller.add(status);
  }
}

/// Proves the epic's ONE `GoRouter`/`redirect` (Boundaries) resolves the
/// I/O & Edge-Case Matrix from spec-1-6 exactly — composing only
/// [SessionStatus] for now, with the AD-14 seam left as a comment, never a
/// hardcoded assumption baked into the matrix itself.
void main() {
  late _FakeSessionRepository fakeSessionRepository;

  setUp(() {
    fakeSessionRepository = _FakeSessionRepository();
    // `/auth`'s `GoRoute.builder` resolves `sl<AuthCubit>()` — registered
    // directly (no full `setupCoreDependencies()`) since this suite only
    // exercises the router, not the auth call itself.
    final mockSessionRepositoryForCubit = MockSessionRepository();
    when(() => mockSessionRepositoryForCubit.markAuthenticated())
        .thenReturn(null);
    sl.registerLazySingleton<AuthCubit>(
      () => AuthCubit(MockAuthRepository(), mockSessionRepositoryForCubit),
    );
  });

  tearDown(() async {
    await sl.reset();
    await fakeSessionRepository.dispose();
  });

  Future<GoRouter> pumpRouter(WidgetTester tester) async {
    final router = buildAppRouter(
      sessionRepository: fakeSessionRepository,
      navigatorKey: GlobalKey<NavigatorState>(),
    );
    addTearDown(router.dispose);
    await tester.pumpWidget(MaterialApp.router(routerConfig: router));
    return router;
  }

  String location(GoRouter router) => router.state.uri.toString();

  testWidgets('status not yet known stays on /boot, splash shown', (
    tester,
  ) async {
    final router = await pumpRouter(tester);
    await tester.pump();

    expect(location(router), AppRoutePaths.boot);
    expect(find.byType(BootSplashScreen), findsOneWidget);
  });

  testWidgets('boot, unauthenticated -> redirected to /auth', (tester) async {
    final router = await pumpRouter(tester);
    fakeSessionRepository.setStatus(SessionStatus.unauthenticated);
    await tester.pumpAndSettle();

    expect(location(router), AppRoutePaths.auth);
    expect(find.byType(AuthScreen), findsOneWidget);
  });

  testWidgets('boot, authenticated -> redirected to /', (tester) async {
    final router = await pumpRouter(tester);
    fakeSessionRepository.setStatus(SessionStatus.authenticated);
    await tester.pumpAndSettle();

    expect(location(router), AppRoutePaths.home);
    expect(find.byType(HomeChatPlaceholderScreen), findsOneWidget);
  });

  testWidgets(
    'boot, expired -> redirected to / (treated the same as authenticated '
    'for routing purposes)',
    (tester) async {
      final router = await pumpRouter(tester);
      fakeSessionRepository.setStatus(SessionStatus.expired);
      await tester.pumpAndSettle();

      expect(location(router), AppRoutePaths.home);
      expect(find.byType(HomeChatPlaceholderScreen), findsOneWidget);
    },
  );

  testWidgets(
    'a mid-session expiry while already on a non-boot/non-auth route never '
    'navigates away (Story 1.5 behavior preserved)',
    (tester) async {
      final router = await pumpRouter(tester);
      fakeSessionRepository.setStatus(SessionStatus.authenticated);
      await tester.pumpAndSettle();

      router.go(AppRoutePaths.meusRegistros);
      await tester.pumpAndSettle();
      expect(location(router), AppRoutePaths.meusRegistros);

      fakeSessionRepository.setStatus(SessionStatus.expired);
      await tester.pumpAndSettle();

      expect(location(router), AppRoutePaths.meusRegistros);
    },
  );

  testWidgets(
    'explicit navigation to /reauth while expired is allowed, not bounced '
    'back to / by the redirect',
    (tester) async {
      final router = await pumpRouter(tester);
      fakeSessionRepository.setStatus(SessionStatus.expired);
      await tester.pumpAndSettle();

      router.go(AppRoutePaths.reauth);
      await tester.pumpAndSettle();

      expect(location(router), AppRoutePaths.reauth);
      expect(find.byType(BiometricReauthPlaceholderScreen), findsOneWidget);
    },
  );

  testWidgets('every destination (/, /meus-registros, /planos-de-acao, '
      '/configuracoes) is reachable with zero broken links while '
      'authenticated', (tester) async {
    final router = await pumpRouter(tester);
    fakeSessionRepository.setStatus(SessionStatus.authenticated);
    await tester.pumpAndSettle();

    for (final destination in [
      AppRoutePaths.meusRegistros,
      AppRoutePaths.planosDeAcao,
      AppRoutePaths.configuracoes,
      AppRoutePaths.home,
    ]) {
      router.go(destination);
      await tester.pumpAndSettle();
      expect(tester.takeException(), isNull);
      expect(location(router), destination);
    }
  });
}

import 'package:dio/dio.dart';

import 'dio_error_code.dart';

/// AD-4 — the one place retry policy lives. Retries only the 6 server
/// `retryable:true` codes (`error-taxonomy.md`); every other failure
/// (including the local `MalformedResponse`) surfaces once, unretried.
///
/// Design note (docs/input is silent on the schedule): fixed 500ms delay,
/// max 2 retries.
class RetryInterceptor extends Interceptor {
  RetryInterceptor(this._dio);

  final Dio _dio;

  /// The 6 server `retryable:true` codes — the only codes this interceptor
  /// ever retries.
  static const Set<String> retryableCodes = {
    'NETWORK_TIMEOUT',
    'NETWORK_OFFLINE',
    'PII_CHECK_FAILED',
    'EMBEDDING_FAILED',
    'AI_GENERATION_TIMEOUT',
    'RATE_LIMITED',
  };

  static const int maxRetries = 2;
  static const Duration retryDelay = Duration(milliseconds: 500);

  static const _attemptKey = 'cerne_retry_attempt';

  @override
  void onError(DioException err, ErrorInterceptorHandler handler) async {
    final attempt = attemptOf(err);

    if (shouldRetry(err, attempt)) {
      await Future<void>.delayed(retryDelay);
      final options = err.requestOptions;
      options.extra[_attemptKey] = attempt + 1;
      try {
        final response = await _dio.fetch<dynamic>(options);
        handler.resolve(response);
      } on DioException catch (retryError) {
        handler.next(retryError);
      } catch (retryError) {
        // Any non-DioException thrown by the retried fetch must still reach
        // the caller through `handler`, never escape unhandled (RNF09).
        handler.next(
          DioException(
            requestOptions: options,
            error: retryError,
            type: DioExceptionType.unknown,
          ),
        );
      }
      return;
    }

    handler.next(err);
  }

  /// How many retries have already been attempted for this request.
  static int attemptOf(DioException err) =>
      (err.requestOptions.extra[_attemptKey] as int?) ?? 0;

  /// The backend error `code` for [err] — delegates to the shared
  /// [dioErrorCodeOf] (also used by `ApiClient`) so a client-side timeout or
  /// a cancelled request is never misread as `NETWORK_OFFLINE` here.
  static String? errorCodeOf(DioException err) => dioErrorCodeOf(err);

  /// Pure decision function, independently testable: retry only if the
  /// error's code is one of the 6 allowlisted codes and the max-retries
  /// budget isn't exhausted yet.
  static bool shouldRetry(DioException err, int attempt) {
    final code = errorCodeOf(err);
    return code != null && retryableCodes.contains(code) && attempt < maxRetries;
  }
}

// ignore_for_file: prefer_initializing_formals
import 'package:dio/dio.dart';
import 'package:flutter/foundation.dart';

import 'access_token_provider.dart';

/// AD-5 — the one interceptor that owns every outgoing request's headers.
/// `apikey` is sent on every call. `Authorization` carries the anon key only
/// on the three `security: []` operations (signup, login, refresh) and the
/// user's access token on every other (`bearerAuth`) operation.
class HeaderInterceptor extends Interceptor {
  HeaderInterceptor({
    required String anonKey,
    required AccessTokenProvider accessTokenProvider,
  })  : _anonKey = anonKey,
        _accessTokenProvider = accessTokenProvider;

  /// The three operations with `security: []` in the contract — the only
  /// ones that ever send the anon key as the bearer token.
  static const anonKeyOnlyFunctions = {
    'auth-signup',
    'auth-login',
    'auth-refresh',
  };

  final String _anonKey;
  final AccessTokenProvider _accessTokenProvider;

  @override
  void onRequest(
    RequestOptions options,
    RequestInterceptorHandler handler,
  ) async {
    options.headers['apikey'] = _anonKey;

    String function;
    try {
      function = functionNameOf(options.path);
    } catch (error) {
      // A malformed `options.path` must never crash/hang the pipeline (an
      // uncaught throw here, before `handler.next` is called, would leave
      // the request unresolved forever) — proceed as if the function were
      // unrecognized rather than let it propagate.
      debugPrint(
        'HeaderInterceptor: functionNameOf failed ($error) for path '
        '"${options.path}" — treating as unrecognized.',
      );
      function = '';
    }
    if (anonKeyOnlyFunctions.contains(function)) {
      options.headers['Authorization'] = 'Bearer $_anonKey';
    } else {
      String? userToken;
      try {
        userToken = await _accessTokenProvider.readAccessToken();
      } catch (error) {
        // A thrown platform exception from the native secure-storage
        // channel must never crash the request pipeline — proceed as if no
        // token were found rather than let it propagate uncaught. Logged so
        // a genuine bug in a future AccessTokenProvider implementation
        // isn't silently invisible.
        debugPrint(
          'HeaderInterceptor: readAccessToken failed ($error) — proceeding '
          'without an Authorization header.',
        );
        userToken = null;
      }
      if (userToken != null) {
        options.headers['Authorization'] = 'Bearer $userToken';
      }
    }

    handler.next(options);
  }

  /// The `x-cerne-function` name is always the first path segment of a URL
  /// built by `UrlBuilder` (whether [path] is the full absolute URL
  /// `ApiClient` sends to `dio`, or a bare `/function/...` path) — pure, so
  /// it's independently testable.
  static String functionNameOf(String path) {
    final segments = Uri.parse(path).pathSegments;
    return segments.isNotEmpty ? segments.first : '';
  }
}

// The constructor keeps public named params (`remoteDataSource`,
// `accessTokenProvider`) distinct from the private fields they initialize,
// matching `auth_repository_impl.dart`'s documented convention.
// ignore_for_file: prefer_initializing_formals
import 'dart:async';

import 'package:fpdart/fpdart.dart';

import '../../../../core/failure/failure.dart';
import '../../../../core/network/access_token_provider.dart';
import '../../../../core/session/session_expiry_notifier.dart';
import '../../domain/entities/session_status.dart';
import '../../domain/repositories/session_repository.dart';
import '../datasources/auth_remote_data_source.dart';

/// Owns the one broadcast [SessionStatus] stream the epic's AD requires.
/// [restoreSession] is unconditional — no client-side expiry math — and
/// covers the I/O matrix (spec-1-4):
/// - no stored refresh token -> no network call, emits `unauthenticated`
///   immediately.
/// - stored token, backend accepts -> new pair persisted via `saveSession`,
///   emits `authenticated`.
/// - stored token, backend reports `AUTH_EXPIRED`/`AUTH_INVALID` (dead
///   token) -> `clearSession`, emits `unauthenticated`.
/// - stored token, any other failure (offline/timeout/...) -> fail-closed:
///   emits `unauthenticated` WITHOUT clearing storage, so the next boot
///   retries naturally.
class SessionRepositoryImpl implements SessionRepository {
  SessionRepositoryImpl({
    required AuthRemoteDataSource remoteDataSource,
    required AccessTokenProvider accessTokenProvider,
    required SessionExpiryNotifier sessionExpiryNotifier,
  }) : _remoteDataSource = remoteDataSource,
       _accessTokenProvider = accessTokenProvider,
       _sessionExpiryNotifier = sessionExpiryNotifier {
    // Story 1.5 — the one bridge from `core`'s expiry signal onto this
    // feature's own `SessionStatus` stream (Design Notes). Subscribed for
    // this repository's whole lifetime; cancelled in [dispose].
    _expirySubscription = _sessionExpiryNotifier.expiredEvents.listen(
      (_) => _onSessionExpired(),
      // Mirrors `statusStream`'s own internal subscription a few lines
      // below: no current `SessionExpiryNotifier` implementation ever
      // errors, but without this, a future one that did would surface as
      // an unhandled zone exception instead of just being dropped here.
      onError: (_, _) {},
    );
  }

  final AuthRemoteDataSource _remoteDataSource;
  final AccessTokenProvider _accessTokenProvider;
  final SessionExpiryNotifier _sessionExpiryNotifier;
  late final StreamSubscription<void> _expirySubscription;
  final StreamController<SessionStatus> _statusController =
      StreamController<SessionStatus>.broadcast();

  /// The last status emitted, so a consumer that subscribes *after* the
  /// first emission (a later `StreamBuilder`, or Story 1.5/1.6's own
  /// listener) still sees current state immediately rather than nothing
  /// until the next change — see [statusStream].
  SessionStatus? _lastStatus;

  @override
  SessionStatus? get currentStatus => _lastStatus;

  @override
  void markAuthenticated() => _emit(SessionStatus.authenticated);

  @override
  Stream<SessionStatus> get statusStream {
    // `Stream.multi` runs this callback once per listener (and, with
    // `isBroadcast: true`, supports more than one simultaneously) — each
    // new listener synchronously gets the cached last status (if any)
    // before being attached to the live broadcast controller for whatever
    // comes next. This is this story's whole reason to not just expose
    // `_statusController.stream` directly: a plain broadcast stream only
    // ever delivers *future* events to a listener that joins late.
    return Stream<SessionStatus>.multi((controller) {
      final last = _lastStatus;
      if (last != null) {
        controller.add(last);
      }
      final subscription = _statusController.stream.listen(
        controller.add,
        onError: controller.addError,
        onDone: controller.close,
      );
      controller.onCancel = subscription.cancel;
    }, isBroadcast: true);
  }

  void _emit(SessionStatus status) {
    // Guards against `dispose()` (wired to `get_it`'s `sl.reset()`) racing
    // an in-flight `restoreSession()` call — without this, a late `.add()`
    // after `.close()` would throw an unhandled `StateError` instead of
    // just being a no-op on an already-torn-down repository.
    if (_statusController.isClosed) {
      return;
    }
    _lastStatus = status;
    _statusController.add(status);
  }

  /// "Always" boundary — a mid-session expiry only ever matters while the
  /// user is currently [SessionStatus.authenticated]; any other current
  /// status (not yet decided at boot, already unauthenticated/logged out,
  /// or already [SessionStatus.expired] from an earlier event) is a
  /// silent no-op — covers both the "expiry while not authenticated"
  /// post-logout race and the "already-open overlay" double-event case in
  /// the I/O matrix (a second event here never re-emits once [_lastStatus]
  /// is already [SessionStatus.expired]).
  void _onSessionExpired() {
    if (_lastStatus == SessionStatus.authenticated) {
      _emit(SessionStatus.expired);
    }
  }

  @override
  Future<Either<Failure, Unit>> restoreSession() async {
    String? refreshToken;
    try {
      refreshToken = await _accessTokenProvider.readRefreshToken();
    } catch (error) {
      // A thrown platform exception from the native secure-storage channel
      // must never escape unmapped (RNF09) — fail closed, same as any other
      // unreadable session.
      _emit(SessionStatus.unauthenticated);
      return left(Failure.malformedResponse(message: error.toString()));
    }

    if (refreshToken == null || refreshToken.isEmpty) {
      // Fresh install / post-logout (null), or a stored-but-empty token
      // (the backend response schema has no `minLength` on `refreshToken`,
      // so an empty string is a theoretically valid stored value) — either
      // way, no network call: `auth-refresh`'s own request schema requires
      // `minLength: 1`, so an empty token would only fail server-side.
      _emit(SessionStatus.unauthenticated);
      return left(
        const Failure.authExpired(message: 'No stored session to restore'),
      );
    }

    final result = await _remoteDataSource.refresh(refreshToken);
    return result.match(
      (failure) async {
        // Only a backend-confirmed dead token clears storage; any other
        // failure (offline, timeout, malformed response, ...) leaves it
        // untouched so the next boot retries naturally.
        if (failure is AuthExpired || failure is AuthInvalid) {
          try {
            await _accessTokenProvider.clearSession();
          } catch (_) {
            // Best-effort clear — the session is already being treated as
            // unauthenticated below regardless of whether this succeeds.
          }
        }
        _emit(SessionStatus.unauthenticated);
        return left(failure);
      },
      (session) async {
        try {
          await _accessTokenProvider.saveSession(
            accessToken: session.accessToken,
            refreshToken: session.refreshToken,
          );
        } catch (error) {
          _emit(SessionStatus.unauthenticated);
          return left(Failure.malformedResponse(message: error.toString()));
        }
        _emit(SessionStatus.authenticated);
        return right(unit);
      },
    );
  }

  @override
  Future<void> dispose() async {
    await _expirySubscription.cancel();
    await _statusController.close();
  }
}

// The constructor keeps public named params (`dio`, `urlBuilder`) distinct
// from the private fields they initialize, so an initializing formal
// (which would force the external name to match) isn't a clean fit here.
// ignore_for_file: prefer_initializing_formals
import 'package:dio/dio.dart';
import 'package:fpdart/fpdart.dart';

import '../failure/failure.dart';
import '../session/session_expiry_notifier.dart';
import 'dio_error_code.dart';
import 'header_interceptor.dart';
import 'url_builder.dart';

/// AD-2/AD-5 — the one network façade every repository's data source calls
/// through. Builds the real URL via `UrlBuilder`, sends the request through
/// `dio` (header + retry interceptors already attached in DI), and maps
/// every outcome — success or failure — to `Either<Failure, T>`; no
/// dio/native exception ever escapes unmapped (RNF09).
///
/// Story 1.5: also the one detection point for a mid-session `AUTH_EXPIRED`
/// — signals [SessionExpiryNotifier] when one is seen outside
/// `HeaderInterceptor.anonKeyOnlyFunctions`, so the boot-time `auth-refresh`
/// call (Story 1.4's `restoreSession()`) never triggers it.
///
/// Tests mock this interface directly (per the architecture spine's testing
/// convention), not a fake transport layer underneath it.
class ApiClient {
  ApiClient({
    required Dio dio,
    required UrlBuilder urlBuilder,
    required SessionExpiryNotifier sessionExpiryNotifier,
  })  : _dio = dio,
        _urlBuilder = urlBuilder,
        _sessionExpiryNotifier = sessionExpiryNotifier;

  final Dio _dio;
  final UrlBuilder _urlBuilder;
  final SessionExpiryNotifier _sessionExpiryNotifier;

  Future<Either<Failure, Map<String, dynamic>>> get(
    String function, {
    List<String> pathParams = const [],
    Map<String, dynamic>? queryParameters,
  }) =>
      _send(
        () => _dio.get<Map<String, dynamic>>(
          _urlBuilder.build(function, pathParams),
          queryParameters: queryParameters,
        ),
      );

  Future<Either<Failure, Map<String, dynamic>>> post(
    String function, {
    List<String> pathParams = const [],
    Object? data,
  }) =>
      _send(
        () => _dio.post<Map<String, dynamic>>(
          _urlBuilder.build(function, pathParams),
          data: data,
        ),
      );

  Future<Either<Failure, Map<String, dynamic>>> patch(
    String function, {
    List<String> pathParams = const [],
    Object? data,
  }) =>
      _send(
        () => _dio.patch<Map<String, dynamic>>(
          _urlBuilder.build(function, pathParams),
          data: data,
        ),
      );

  Future<Either<Failure, Map<String, dynamic>>> delete(
    String function, {
    List<String> pathParams = const [],
    Object? data,
  }) =>
      _send(
        () => _dio.delete<Map<String, dynamic>>(
          _urlBuilder.build(function, pathParams),
          data: data,
        ),
      );

  Future<Either<Failure, Map<String, dynamic>>> _send(
    Future<Response<Map<String, dynamic>>> Function() request,
  ) async {
    try {
      final response = await request();
      final data = response.data;
      if (data == null) {
        return left(
          const Failure.malformedResponse(message: 'Empty response body'),
        );
      }
      return right(data);
    } on DioException catch (e) {
      return left(_mapDioException(e));
    } catch (e) {
      return left(Failure.malformedResponse(message: e.toString()));
    }
  }

  Failure _mapDioException(DioException e) {
    final code = dioErrorCodeOf(e);
    if (code == null) {
      // Covers a cancelled request and an HTTP response that doesn't carry
      // the expected `{code, message, retryable}` body — neither is one of
      // the 13 backend codes, so neither is retryable (dioErrorCodeOf).
      return Failure.malformedResponse(
        message: e.message ?? 'Malformed response',
      );
    }
    final data = e.response?.data;
    final message = data is Map ? data['message'] : null;
    final failure = Failure.fromCode(
      code,
      (message is String ? message : null) ?? e.message ?? 'Unknown error',
    );
    if (failure is AuthExpired && !_isAnonKeyOnlyCall(e)) {
      _sessionExpiryNotifier.notifyExpired();
    }
    return failure;
  }

  /// Whether [e]'s request targeted one of the three `security: []`
  /// operations (signup, login, refresh) — the only calls `AUTH_EXPIRED`
  /// must never be treated as a mid-session expiry for, since those are the
  /// anon-keyed calls Story 1.4's `restoreSession()` itself makes.
  ///
  /// Mirrors `HeaderInterceptor.onRequest`'s own fail-open behavior: a
  /// malformed `requestOptions.path` (shouldn't happen — `UrlBuilder`
  /// always produces a valid URL) is treated as "not anon-key-only" rather
  /// than letting a `FormatException` escape this mapping step unmapped
  /// (RNF09).
  bool _isAnonKeyOnlyCall(DioException e) {
    String function;
    try {
      function = HeaderInterceptor.functionNameOf(e.requestOptions.path);
    } catch (_) {
      function = '';
    }
    return HeaderInterceptor.anonKeyOnlyFunctions.contains(function);
  }
}

import 'dart:async';

import 'package:flutter_test/flutter_test.dart';
import 'package:fpdart/fpdart.dart';
import 'package:mocktail/mocktail.dart';

import 'package:cerne/core/failure/failure.dart';
import 'package:cerne/core/network/access_token_provider.dart';
import 'package:cerne/features/auth/data/datasources/auth_remote_data_source.dart';
import 'package:cerne/features/auth/data/models/auth_response_dto.dart';
import 'package:cerne/features/auth/data/repositories/session_repository_impl.dart';
import 'package:cerne/features/auth/domain/entities/session_status.dart';

import '../../../../support/mock_session_expiry_notifier.dart';

class MockAuthRemoteDataSource extends Mock implements AuthRemoteDataSource {}

class MockAccessTokenProvider extends Mock implements AccessTokenProvider {}

const _newSession = AuthSessionDto(
  accessToken: 'new-access-token',
  refreshToken: 'new-refresh-token',
  expiresIn: 3600,
  expiresAt: 1999999999,
  tokenType: 'bearer',
);

void main() {
  late MockAuthRemoteDataSource mockRemoteDataSource;
  late MockAccessTokenProvider mockAccessTokenProvider;
  late MockSessionExpiryNotifier mockSessionExpiryNotifier;
  late StreamController<void> expiryController;
  late SessionRepositoryImpl repository;

  setUp(() {
    mockRemoteDataSource = MockAuthRemoteDataSource();
    mockAccessTokenProvider = MockAccessTokenProvider();
    mockSessionExpiryNotifier = MockSessionExpiryNotifier();
    expiryController = StreamController<void>.broadcast();
    when(() => mockSessionExpiryNotifier.expiredEvents)
        .thenAnswer((_) => expiryController.stream);
    when(
      () => mockAccessTokenProvider.saveSession(
        accessToken: any(named: 'accessToken'),
        refreshToken: any(named: 'refreshToken'),
      ),
    ).thenAnswer((_) async {});
    when(() => mockAccessTokenProvider.clearSession()).thenAnswer((_) async {});
    repository = SessionRepositoryImpl(
      remoteDataSource: mockRemoteDataSource,
      accessTokenProvider: mockAccessTokenProvider,
      sessionExpiryNotifier: mockSessionExpiryNotifier,
    );
  });

  tearDown(() async {
    await expiryController.close();
  });

  /// Subscribes before [restoreSession] runs (required for a broadcast
  /// stream) and drains the microtask queue afterwards so the event posted
  /// by `_statusController.add(...)` has definitely been delivered by the
  /// time this returns — same rationale as `auth_cubit_test.dart`'s
  /// `_emittedDuring` helper.
  Future<List<SessionStatus>> emittedDuring(Future<void> Function() act) async {
    final emitted = <SessionStatus>[];
    final subscription = repository.statusStream.listen(emitted.add);
    await act();
    await Future<void>.delayed(Duration.zero);
    await subscription.cancel();
    return emitted;
  }

  group('cold boot, valid refresh token', () {
    test('auth-refresh succeeds -> new pair saved, stream emits '
        'authenticated, Right(unit) returned', () async {
      when(() => mockAccessTokenProvider.readRefreshToken())
          .thenAnswer((_) async => 'stored-refresh-token');
      when(() => mockRemoteDataSource.refresh('stored-refresh-token'))
          .thenAnswer((_) async => right(_newSession));

      Either<Failure, Unit>? result;
      final emitted = await emittedDuring(() async {
        result = await repository.restoreSession();
      });

      expect(emitted, [SessionStatus.authenticated]);
      expect(result!.isRight(), isTrue);
      verify(
        () => mockAccessTokenProvider.saveSession(
          accessToken: 'new-access-token',
          refreshToken: 'new-refresh-token',
        ),
      ).called(1);
      verifyNever(() => mockAccessTokenProvider.clearSession());
    });
  });

  group('cold boot, no stored session', () {
    test('no refresh token -> no network call, stream emits unauthenticated '
        'immediately', () async {
      when(() => mockAccessTokenProvider.readRefreshToken())
          .thenAnswer((_) async => null);

      Either<Failure, Unit>? result;
      final emitted = await emittedDuring(() async {
        result = await repository.restoreSession();
      });

      expect(emitted, [SessionStatus.unauthenticated]);
      expect(result!.isLeft(), isTrue);
      result!.match(
        (failure) => expect(failure, isA<AuthExpired>()),
        (_) => fail('expected Left'),
      );
      verifyNever(() => mockRemoteDataSource.refresh(any()));
      verifyNever(
        () => mockAccessTokenProvider.saveSession(
          accessToken: any(named: 'accessToken'),
          refreshToken: any(named: 'refreshToken'),
        ),
      );
      verifyNever(() => mockAccessTokenProvider.clearSession());
    });

    test('stored-but-empty refresh token -> treated the same as no token: '
        'no network call, stream emits unauthenticated', () async {
      when(() => mockAccessTokenProvider.readRefreshToken())
          .thenAnswer((_) async => '');

      Either<Failure, Unit>? result;
      final emitted = await emittedDuring(() async {
        result = await repository.restoreSession();
      });

      expect(emitted, [SessionStatus.unauthenticated]);
      expect(result!.isLeft(), isTrue);
      result!.match(
        (failure) => expect(failure, isA<AuthExpired>()),
        (_) => fail('expected Left'),
      );
      verifyNever(() => mockRemoteDataSource.refresh(any()));
    });
  });

  group('cold boot, dead refresh token', () {
    test(
      'backend returns AUTH_EXPIRED -> session cleared, stream emits '
      'unauthenticated, silently (Left surfaced to the caller only)',
      () async {
        when(() => mockAccessTokenProvider.readRefreshToken())
            .thenAnswer((_) async => 'dead-refresh-token');
        when(
          () => mockRemoteDataSource.refresh('dead-refresh-token'),
        ).thenAnswer(
          (_) async =>
              left(const Failure.authExpired(message: 'Refresh token dead')),
        );

        Either<Failure, Unit>? result;
        final emitted = await emittedDuring(() async {
          result = await repository.restoreSession();
        });

        expect(emitted, [SessionStatus.unauthenticated]);
        expect(result!.isLeft(), isTrue);
        result!.match(
          (failure) => expect(failure, isA<AuthExpired>()),
          (_) => fail('expected Left'),
        );
        verify(() => mockAccessTokenProvider.clearSession()).called(1);
      },
    );

    test('backend returns AUTH_INVALID -> session cleared, stream emits '
        'unauthenticated', () async {
      when(() => mockAccessTokenProvider.readRefreshToken())
          .thenAnswer((_) async => 'invalid-refresh-token');
      when(
        () => mockRemoteDataSource.refresh('invalid-refresh-token'),
      ).thenAnswer(
        (_) async =>
            left(const Failure.authInvalid(message: 'Refresh token invalid')),
      );

      final emitted = await emittedDuring(() async {
        await repository.restoreSession();
      });

      expect(emitted, [SessionStatus.unauthenticated]);
      verify(() => mockAccessTokenProvider.clearSession()).called(1);
    });
  });

  group('Story 1.6 — currentStatus / markAuthenticated', () {
    test('currentStatus is null before any emission', () {
      expect(repository.currentStatus, isNull);
    });

    test(
      'currentStatus mirrors the last value emitted on statusStream',
      () async {
        when(() => mockAccessTokenProvider.readRefreshToken())
            .thenAnswer((_) async => null);

        await repository.restoreSession();

        expect(repository.currentStatus, SessionStatus.unauthenticated);
      },
    );

    test('markAuthenticated() synchronously flips currentStatus to '
        'authenticated and emits it on statusStream, with no network/'
        'storage call', () async {
      final emitted = await emittedDuring(() async {
        repository.markAuthenticated();
      });

      expect(repository.currentStatus, SessionStatus.authenticated);
      expect(emitted, [SessionStatus.authenticated]);
      verifyNever(() => mockRemoteDataSource.refresh(any()));
      verifyNever(
        () => mockAccessTokenProvider.saveSession(
          accessToken: any(named: 'accessToken'),
          refreshToken: any(named: 'refreshToken'),
        ),
      );
    });
  });

  group('statusStream replay semantics', () {
    test('a listener that subscribes AFTER restoreSession() has already '
        'emitted still immediately sees the current status, not nothing '
        'until the next change', () async {
      when(() => mockAccessTokenProvider.readRefreshToken())
          .thenAnswer((_) async => null);

      await repository.restoreSession();

      // No prior subscription here — this is the late-joining listener
      // `Stream.multi` replay exists for.
      final status = await repository.statusStream.first;

      expect(status, SessionStatus.unauthenticated);
    });
  });

  group('platform exceptions never escape unmapped (RNF09)', () {
    test('readRefreshToken() throws -> Left(MalformedResponse), stream emits '
        'unauthenticated, no network call', () async {
      when(() => mockAccessTokenProvider.readRefreshToken())
          .thenThrow(Exception('secure storage unavailable'));

      Either<Failure, Unit>? result;
      final emitted = await emittedDuring(() async {
        result = await repository.restoreSession();
      });

      expect(emitted, [SessionStatus.unauthenticated]);
      expect(result!.isLeft(), isTrue);
      result!.match(
        (failure) => expect(failure, isA<MalformedResponse>()),
        (_) => fail('expected Left'),
      );
      verifyNever(() => mockRemoteDataSource.refresh(any()));
    });

    test('saveSession() throws after a successful refresh -> '
        'Left(MalformedResponse), stream emits unauthenticated', () async {
      when(() => mockAccessTokenProvider.readRefreshToken())
          .thenAnswer((_) async => 'stored-refresh-token');
      when(() => mockRemoteDataSource.refresh('stored-refresh-token'))
          .thenAnswer((_) async => right(_newSession));
      when(
        () => mockAccessTokenProvider.saveSession(
          accessToken: any(named: 'accessToken'),
          refreshToken: any(named: 'refreshToken'),
        ),
      ).thenThrow(Exception('secure storage unavailable'));

      Either<Failure, Unit>? result;
      final emitted = await emittedDuring(() async {
        result = await repository.restoreSession();
      });

      expect(emitted, [SessionStatus.unauthenticated]);
      expect(result!.isLeft(), isTrue);
      result!.match(
        (failure) => expect(failure, isA<MalformedResponse>()),
        (_) => fail('expected Left'),
      );
    });
  });

  group('cold boot, offline', () {
    test('no connectivity -> stream emits unauthenticated (fail-closed), '
        'storage left untouched', () async {
      when(() => mockAccessTokenProvider.readRefreshToken())
          .thenAnswer((_) async => 'stored-refresh-token');
      when(() => mockRemoteDataSource.refresh('stored-refresh-token'))
          .thenAnswer(
            (_) async => left(const Failure.networkOffline(message: 'Offline')),
          );

      Either<Failure, Unit>? result;
      final emitted = await emittedDuring(() async {
        result = await repository.restoreSession();
      });

      expect(emitted, [SessionStatus.unauthenticated]);
      expect(result!.isLeft(), isTrue);
      result!.match(
        (failure) => expect(failure, isA<NetworkOffline>()),
        (_) => fail('expected Left'),
      );
      // Fail-closed, but the stored token is NOT cleared — only a
      // backend-confirmed dead token (AUTH_EXPIRED/AUTH_INVALID) clears it.
      verifyNever(() => mockAccessTokenProvider.clearSession());
    });
  });

  group('Story 1.5 — SessionExpiryNotifier bridged onto statusStream', () {
    test('a mid-session expiry event while authenticated -> stream emits '
        'expired', () async {
      when(() => mockAccessTokenProvider.readRefreshToken())
          .thenAnswer((_) async => 'stored-refresh-token');
      when(() => mockRemoteDataSource.refresh('stored-refresh-token'))
          .thenAnswer((_) async => right(_newSession));

      final emitted = await emittedDuring(() async {
        await repository.restoreSession();
        expiryController.add(null);
        await Future<void>.delayed(Duration.zero);
      });

      expect(emitted, [SessionStatus.authenticated, SessionStatus.expired]);
    });

    test('an expiry event while unauthenticated (post-logout race) is a '
        'silent no-op — no emission, no overlay', () async {
      when(() => mockAccessTokenProvider.readRefreshToken())
          .thenAnswer((_) async => null);

      final emitted = await emittedDuring(() async {
        await repository.restoreSession();
        expiryController.add(null);
        await Future<void>.delayed(Duration.zero);
      });

      expect(emitted, [SessionStatus.unauthenticated]);
    });

    test('an expiry event before restoreSession() has ever emitted (no '
        'current status yet) is a silent no-op', () async {
      final emitted = await emittedDuring(() async {
        expiryController.add(null);
        await Future<void>.delayed(Duration.zero);
      });

      expect(emitted, isEmpty);
    });

    test('a second expiry event while already expired does not re-emit — the '
        "single-overlay guard holds at the repository's own stream, not only "
        'in the UI', () async {
      when(() => mockAccessTokenProvider.readRefreshToken())
          .thenAnswer((_) async => 'stored-refresh-token');
      when(() => mockRemoteDataSource.refresh('stored-refresh-token'))
          .thenAnswer((_) async => right(_newSession));

      final emitted = await emittedDuring(() async {
        await repository.restoreSession();
        expiryController.add(null);
        await Future<void>.delayed(Duration.zero);
        expiryController.add(null);
        await Future<void>.delayed(Duration.zero);
      });

      expect(emitted, [SessionStatus.authenticated, SessionStatus.expired]);
    });

    test('dispose() cancels the expiry subscription — a later event never '
        'reaches the (already-closed) statusStream', () async {
      when(() => mockAccessTokenProvider.readRefreshToken())
          .thenAnswer((_) async => 'stored-refresh-token');
      when(() => mockRemoteDataSource.refresh('stored-refresh-token'))
          .thenAnswer((_) async => right(_newSession));

      final emitted = await emittedDuring(() async {
        await repository.restoreSession();
        await repository.dispose();
        // If `dispose()` ever stopped cancelling `_expirySubscription`,
        // this would still reach `_onSessionExpired()` and — since
        // `_lastStatus` is still `authenticated` — attempt to `_emit()`
        // `expired`. The `isClosed` guard in `_emit()` would swallow that
        // silently, so only actually observing `statusStream` (not just
        // asserting `add()` doesn't throw) can tell the two apart.
        expiryController.add(null);
        await Future<void>.delayed(Duration.zero);
      });

      expect(emitted, [SessionStatus.authenticated]);
    });
  });
}

import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:fpdart/fpdart.dart' hide State;
import 'package:go_router/go_router.dart';

import 'package:cerne/core/failure/failure.dart';
import 'package:cerne/core/navigation/expiry_overlay_host.dart';
import 'package:cerne/core/widgets/confirmation_dialog.dart';
import 'package:cerne/features/auth/domain/entities/session_status.dart';
import 'package:cerne/features/auth/domain/repositories/session_repository.dart';

/// Same tiny fake used by `app_router_test.dart`/`main_test.dart` — gives
/// synchronous control over both [SessionStatus] values and the
/// [statusStream] emission `ExpiryOverlayHost` subscribes to.
class _FakeSessionRepository implements SessionRepository {
  SessionStatus? _status;
  final _controller = StreamController<SessionStatus>.broadcast();

  @override
  SessionStatus? get currentStatus => _status;

  @override
  Stream<SessionStatus> get statusStream => _controller.stream;

  @override
  Future<Either<Failure, Unit>> restoreSession() async => right(unit);

  @override
  void markAuthenticated() => setStatus(SessionStatus.authenticated);

  @override
  Future<void> dispose() => _controller.close();

  void setStatus(SessionStatus status) {
    _status = status;
    _controller.add(status);
  }
}

void main() {
  setUp(() {
    ConfirmationDialog.isOpen = false;
  });

  testWidgets('an expired emission before the Navigator behind navigatorKey is '
      'mounted finds no overlay context, does not throw, and resets its '
      'one-shot guard so a later mount can still show the overlay', (
    tester,
  ) async {
    final fakeSessionRepository = _FakeSessionRepository();
    addTearDown(fakeSessionRepository.dispose);
    final router = GoRouter(
      routes: [
        GoRoute(path: '/', builder: (context, state) => const SizedBox()),
      ],
    );
    addTearDown(router.dispose);
    final navigatorKey = GlobalKey<NavigatorState>();

    // First mount: `navigatorKey` matches nothing in this tree — no
    // `Navigator` anywhere uses it — simulating the Navigator not being
    // mounted yet when the expiry event arrives.
    await tester.pumpWidget(
      Directionality(
        textDirection: TextDirection.ltr,
        child: ExpiryOverlayHost(
          sessionRepository: fakeSessionRepository,
          router: router,
          navigatorKey: navigatorKey,
          child: const SizedBox(),
        ),
      ),
    );

    fakeSessionRepository.setStatus(SessionStatus.expired);
    await tester.pumpAndSettle();

    expect(tester.takeException(), isNull);
    expect(find.byType(ConfirmationDialog), findsNothing);

    // Second pump of the *same* `ExpiryOverlayHost` (same type, no key,
    // same position — its State is preserved, not remounted): now the
    // child actually contains a `Navigator` using `navigatorKey`, so
    // `navigatorKey.currentState` resolves. Re-emitting `expired` here
    // only shows the overlay if the earlier failed attempt reset
    // `_expiryOverlayShown` back to `false` — if that guard had stayed
    // stuck `true`, this second, now-resolvable attempt would stay
    // silently dropped too.
    await tester.pumpWidget(
      Directionality(
        textDirection: TextDirection.ltr,
        child: ExpiryOverlayHost(
          sessionRepository: fakeSessionRepository,
          router: router,
          navigatorKey: navigatorKey,
          child: Navigator(
            key: navigatorKey,
            onGenerateRoute: (settings) =>
                MaterialPageRoute<void>(builder: (context) => const SizedBox()),
          ),
        ),
      ),
    );

    fakeSessionRepository.setStatus(SessionStatus.expired);
    await tester.pumpAndSettle();

    expect(tester.takeException(), isNull);
    expect(find.text('Sessão expirada'), findsOneWidget);
  });
}

