import 'package:dio/dio.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:mocktail/mocktail.dart';

import 'package:cerne/core/network/access_token_provider.dart';
import 'package:cerne/core/network/header_interceptor.dart';

class MockAccessTokenProvider extends Mock implements AccessTokenProvider {}

class MockRequestInterceptorHandler extends Mock
    implements RequestInterceptorHandler {}

void main() {
  setUpAll(() {
    registerFallbackValue(RequestOptions(path: '/fallback'));
  });

  const anonKey = 'anon-key-value';

  late MockAccessTokenProvider mockAccessTokenProvider;
  late HeaderInterceptor interceptor;

  setUp(() {
    mockAccessTokenProvider = MockAccessTokenProvider();
    interceptor = HeaderInterceptor(
      anonKey: anonKey,
      accessTokenProvider: mockAccessTokenProvider,
    );
  });

  group('HeaderInterceptor.onRequest — AD-5 header policy', () {
    test('anon-only function (auth-login) sends apikey + anon bearer', () {
      final options = RequestOptions(path: 'https://host/auth-login');
      final handler = MockRequestInterceptorHandler();
      when(() => handler.next(any())).thenReturn(null);

      interceptor.onRequest(options, handler);

      expect(options.headers['apikey'], anonKey);
      expect(options.headers['Authorization'], 'Bearer $anonKey');
      verify(() => handler.next(options)).called(1);
      verifyNever(() => mockAccessTokenProvider.readAccessToken());
    });

    test('other function with a stored token sends apikey + user bearer',
        () async {
      const userToken = 'user-token-value';
      when(() => mockAccessTokenProvider.readAccessToken())
          .thenAnswer((_) async => userToken);

      final options = RequestOptions(path: 'https://host/entries-create');
      final handler = MockRequestInterceptorHandler();
      when(() => handler.next(any())).thenReturn(null);

      await _runOnRequest(interceptor, options, handler);

      expect(options.headers['apikey'], anonKey);
      expect(options.headers['Authorization'], 'Bearer $userToken');
      verify(() => handler.next(options)).called(1);
    });

    test('other function with no stored token sends apikey, no Authorization',
        () async {
      when(() => mockAccessTokenProvider.readAccessToken())
          .thenAnswer((_) async => null);

      final options = RequestOptions(path: 'https://host/entries-list');
      final handler = MockRequestInterceptorHandler();
      when(() => handler.next(any())).thenReturn(null);

      await _runOnRequest(interceptor, options, handler);

      expect(options.headers['apikey'], anonKey);
      expect(options.headers.containsKey('Authorization'), isFalse);
      verify(() => handler.next(options)).called(1);
    });

    test(
        'a thrown PlatformException from readAccessToken never crashes the '
        'pipeline — proceeds with no Authorization header', () async {
      when(() => mockAccessTokenProvider.readAccessToken())
          .thenThrow(Exception('secure storage unavailable'));

      final options = RequestOptions(path: 'https://host/entries-list');
      final handler = MockRequestInterceptorHandler();
      when(() => handler.next(any())).thenReturn(null);

      await _runOnRequest(interceptor, options, handler);

      expect(options.headers['apikey'], anonKey);
      expect(options.headers.containsKey('Authorization'), isFalse);
      verify(() => handler.next(options)).called(1);
    });

    test(
        'a path that makes functionNameOf throw (malformed percent-escape) '
        'still completes instead of hanging the request', () async {
      when(() => mockAccessTokenProvider.readAccessToken())
          .thenAnswer((_) async => null);

      final options = RequestOptions(path: 'https://host/%');
      final handler = MockRequestInterceptorHandler();
      when(() => handler.next(any())).thenReturn(null);

      await _runOnRequest(interceptor, options, handler);

      expect(options.headers['apikey'], anonKey);
      verify(() => handler.next(options)).called(1);
    });
  });

  group('HeaderInterceptor.functionNameOf', () {
    test('a bare function path with no path params', () {
      expect(
        HeaderInterceptor.functionNameOf('https://host/auth-login'),
        'auth-login',
      );
    });

    test('a function path with trailing path params', () {
      expect(
        HeaderInterceptor.functionNameOf(
          'https://host/chat-messages-retry/session-1/message-1',
        ),
        'chat-messages-retry',
      );
    });

    test('a bare relative path (no scheme/host)', () {
      expect(HeaderInterceptor.functionNameOf('/auth-signup'), 'auth-signup');
    });
  });
}

/// `onRequest` is declared `void` but implemented `async`, so Dart still
/// returns a real `Future` at runtime even though the static type hides it
/// — awaiting that real Future deterministically waits for the method's
/// async work to finish, instead of a fixed-duration sleep.
Future<void> _runOnRequest(
  HeaderInterceptor interceptor,
  RequestOptions options,
  RequestInterceptorHandler handler,
) async {
  // `onRequest`'s declared return type is `void`, but the real
  // implementation is `async` and returns a real `Future` at runtime.
  // Calling through a `dynamic`-typed reference bypasses the static void
  // check so that real Future can be captured and awaited.
  final dynamic pending = (interceptor.onRequest as dynamic)(options, handler);
  if (pending is Future) await pending;
}

import 'package:dio/dio.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:mocktail/mocktail.dart';

import 'package:cerne/core/network/retry_interceptor.dart';

class MockDio extends Mock implements Dio {}

class MockErrorInterceptorHandler extends Mock
    implements ErrorInterceptorHandler {}

DioException _errorWithCode(
  String code, {
  RequestOptions? requestOptions,
}) {
  final options = requestOptions ?? RequestOptions(path: '/some-function');
  return DioException(
    requestOptions: options,
    response: Response(
      requestOptions: options,
      statusCode: 502,
      data: {'code': code, 'message': 'boom', 'retryable': true},
    ),
    type: DioExceptionType.badResponse,
  );
}

DioException _connectionErrorWithNoResponse({RequestOptions? requestOptions}) {
  final options = requestOptions ?? RequestOptions(path: '/some-function');
  return DioException(
    requestOptions: options,
    type: DioExceptionType.connectionError,
  );
}

void main() {
  setUpAll(() {
    final fallbackOptions = RequestOptions(path: '/fallback');
    registerFallbackValue(fallbackOptions);
    registerFallbackValue(Response<dynamic>(requestOptions: fallbackOptions));
    registerFallbackValue(
      DioException(requestOptions: fallbackOptions),
    );
  });

  group('RetryInterceptor.errorCodeOf', () {
    test('reads the code from the response body when present', () {
      final err = _errorWithCode('RATE_LIMITED');
      expect(RetryInterceptor.errorCodeOf(err), 'RATE_LIMITED');
    });

    test('maps a response-less connection error to NETWORK_OFFLINE', () {
      final err = _connectionErrorWithNoResponse();
      expect(RetryInterceptor.errorCodeOf(err), 'NETWORK_OFFLINE');
    });

    test(
        'maps a client-side connect timeout to NETWORK_TIMEOUT, not '
        'NETWORK_OFFLINE', () {
      final err = DioException(
        requestOptions: RequestOptions(path: '/some-function'),
        type: DioExceptionType.connectionTimeout,
      );
      expect(RetryInterceptor.errorCodeOf(err), 'NETWORK_TIMEOUT');
    });

    test('a cancelled request has no code (never retryable)', () {
      final err = DioException(
        requestOptions: RequestOptions(path: '/some-function'),
        type: DioExceptionType.cancel,
      );
      expect(RetryInterceptor.errorCodeOf(err), isNull);
    });
  });

  group('RetryInterceptor.shouldRetry — only the 6 retryable codes, AD-4', () {
    const retryableCodes = {
      'NETWORK_TIMEOUT',
      'NETWORK_OFFLINE',
      'PII_CHECK_FAILED',
      'EMBEDDING_FAILED',
      'AI_GENERATION_TIMEOUT',
      'RATE_LIMITED',
    };

    const nonRetryableCodes = {
      'AUTH_EXPIRED',
      'AUTH_INVALID',
      'VALIDATION_ERROR',
      'NOT_FOUND',
      'EXPORT_EMPTY_PERIOD',
      'PAYLOAD_TOO_LARGE',
      'OCR_NO_TEXT',
    };

    for (final code in retryableCodes) {
      test('$code retries on first attempt', () {
        final err = _errorWithCode(code);
        expect(RetryInterceptor.shouldRetry(err, 0), isTrue);
      });
    }

    for (final code in nonRetryableCodes) {
      test('$code never retries', () {
        final err = _errorWithCode(code);
        expect(RetryInterceptor.shouldRetry(err, 0), isFalse);
      });
    }

    test('stops retrying once maxRetries (2) is reached', () {
      final err = _errorWithCode('NETWORK_TIMEOUT');
      expect(RetryInterceptor.shouldRetry(err, 0), isTrue);
      expect(RetryInterceptor.shouldRetry(err, 1), isTrue);
      expect(RetryInterceptor.shouldRetry(err, 2), isFalse);
    });

    test('a cancelled request is never retried', () {
      final err = DioException(
        requestOptions: RequestOptions(path: '/some-function'),
        type: DioExceptionType.cancel,
      );
      expect(RetryInterceptor.shouldRetry(err, 0), isFalse);
    });

    test('a client-side connect timeout retries like a server timeout', () {
      final err = DioException(
        requestOptions: RequestOptions(path: '/some-function'),
        type: DioExceptionType.connectionTimeout,
      );
      expect(RetryInterceptor.shouldRetry(err, 0), isTrue);
    });
  });

  group('RetryInterceptor.onError — end-to-end retry behavior', () {
    late MockDio mockDio;
    late RetryInterceptor interceptor;

    setUp(() {
      mockDio = MockDio();
      interceptor = RetryInterceptor(mockDio);
    });

    test('retries a retryable error and resolves on success', () async {
      final options = RequestOptions(path: '/chat-messages-send');
      final err = _errorWithCode('AI_GENERATION_TIMEOUT', requestOptions: options);
      final successResponse = Response<dynamic>(
        requestOptions: options,
        statusCode: 200,
        data: {'ok': true},
      );

      when(() => mockDio.fetch<dynamic>(any()))
          .thenAnswer((_) async => successResponse);

      final handler = MockErrorInterceptorHandler();
      when(() => handler.resolve(any())).thenReturn(null);

      await _runOnError(interceptor, err, handler);

      verify(() => mockDio.fetch<dynamic>(any())).called(1);
      verify(() => handler.resolve(successResponse)).called(1);
    });

    test('never retries a non-retryable error', () async {
      final options = RequestOptions(path: '/auth-login');
      final err = _errorWithCode('AUTH_INVALID', requestOptions: options);

      final handler = MockErrorInterceptorHandler();
      when(() => handler.next(any())).thenReturn(null);

      await _runOnError(interceptor, err, handler);

      verifyNever(() => mockDio.fetch<dynamic>(any()));
      verify(() => handler.next(err)).called(1);
    });

    test(
      'retry-exhausted: a retryable code keeps failing through all '
      'maxRetries attempts, finally calling handler.next and never '
      'handler.resolve',
      () async {
        final options = RequestOptions(path: '/chat-messages-send');

        when(() => mockDio.fetch<dynamic>(any())).thenAnswer((invocation) {
          final opts = invocation.positionalArguments.first as RequestOptions;
          throw DioException(
            requestOptions: opts,
            response: Response(
              requestOptions: opts,
              statusCode: 504,
              data: {
                'code': 'NETWORK_TIMEOUT',
                'message': 'timeout',
                'retryable': true,
              },
            ),
            type: DioExceptionType.badResponse,
          );
        });

        final handler = MockErrorInterceptorHandler();
        when(() => handler.next(any())).thenReturn(null);
        when(() => handler.resolve(any())).thenReturn(null);

        DioException currentError =
            _errorWithCode('NETWORK_TIMEOUT', requestOptions: options);

        // Simulates the real Dio pipeline re-entering onError after each
        // failed retry (a bare mock doesn't loop by itself), carrying the
        // incremented attempt count forward each round, through and past
        // maxRetries.
        for (var round = 0; round <= RetryInterceptor.maxRetries; round++) {
          await _runOnError(interceptor, currentError, handler);

          final captured =
              verify(() => handler.next(captureAny())).captured;
          currentError = captured.last as DioException;
        }

        expect(
          RetryInterceptor.attemptOf(currentError),
          RetryInterceptor.maxRetries,
        );
        verify(() => mockDio.fetch<dynamic>(any()))
            .called(RetryInterceptor.maxRetries);
        verifyNever(() => handler.resolve(any()));
      },
    );
  });
}

/// `onError` is declared `void` but implemented `async`, so Dart still
/// returns a real `Future` at runtime even though the static type hides it
/// — awaiting that real Future deterministically waits for the retry
/// delay + fetch to finish, instead of a fixed-duration sleep.
Future<void> _runOnError(
  RetryInterceptor interceptor,
  DioException err,
  ErrorInterceptorHandler handler,
) async {
  // `onError`'s declared return type is `void`, but the real implementation
  // is `async` and returns a real `Future` at runtime. Calling through a
  // `dynamic`-typed reference bypasses the static void check so that real
  // Future can be captured and awaited.
  final dynamic pending = (interceptor.onError as dynamic)(err, handler);
  if (pending is Future) await pending;
}

import 'package:dio/dio.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:mocktail/mocktail.dart';

import 'package:cerne/core/failure/failure.dart';
import 'package:cerne/core/network/api_client.dart';
import 'package:cerne/core/network/url_builder.dart';

import '../../support/mock_session_expiry_notifier.dart';

class MockDio extends Mock implements Dio {}

void main() {
  const baseUrl = 'https://host.example.com';

  late MockDio mockDio;
  late MockSessionExpiryNotifier mockSessionExpiryNotifier;
  late ApiClient apiClient;
  late RequestOptions requestOptions;

  setUp(() {
    mockDio = MockDio();
    mockSessionExpiryNotifier = MockSessionExpiryNotifier();
    apiClient = ApiClient(
      dio: mockDio,
      urlBuilder: const UrlBuilder(baseUrl),
      sessionExpiryNotifier: mockSessionExpiryNotifier,
    );
    requestOptions = RequestOptions(path: '$baseUrl/auth-signup');
  });

  group('ApiClient — real send/mapping logic, mocked Dio', () {
    test('success response -> Right(data)', () async {
      final response = Response<Map<String, dynamic>>(
        requestOptions: requestOptions,
        statusCode: 200,
        data: {'id': 'abc123'},
      );
      when(
        () =>
            mockDio.post<Map<String, dynamic>>(any(), data: any(named: 'data')),
      ).thenAnswer((_) async => response);

      final result = await apiClient.post('auth-signup', data: {'a': 1});

      expect(result.isRight(), isTrue);
      result.match(
        (_) => fail('expected Right'),
        (data) => expect(data, {'id': 'abc123'}),
      );
    });

    test('DioException with a {code, message} body maps to the matching '
        'Failure', () async {
      final dioError = DioException(
        requestOptions: requestOptions,
        response: Response(
          requestOptions: requestOptions,
          statusCode: 429,
          data: {
            'code': 'RATE_LIMITED',
            'message': 'Too many requests',
            'retryable': true,
          },
        ),
        type: DioExceptionType.badResponse,
      );
      when(
        () =>
            mockDio.post<Map<String, dynamic>>(any(), data: any(named: 'data')),
      ).thenThrow(dioError);

      final result = await apiClient.post('auth-signup', data: {'a': 1});

      expect(result.isLeft(), isTrue);
      result.match((failure) {
        expect(failure, isA<RateLimited>());
        expect(failure.retryable, isTrue);
      }, (_) => fail('expected Left'));
    });

    test('a {code, message} body where message is not a String still maps '
        'without throwing (patch item 1)', () async {
      final dioError = DioException(
        requestOptions: requestOptions,
        response: Response(
          requestOptions: requestOptions,
          statusCode: 400,
          data: {
            'code': 'VALIDATION_ERROR',
            // Malformed on purpose: the contract says `message` is a
            // String, but nothing stops a backend bug from sending an int.
            'message': 12345,
            'retryable': false,
          },
        ),
        type: DioExceptionType.badResponse,
      );
      when(
        () =>
            mockDio.post<Map<String, dynamic>>(any(), data: any(named: 'data')),
      ).thenThrow(dioError);

      final result = await apiClient.post('auth-signup', data: {'a': 1});

      expect(result.isLeft(), isTrue);
      result.match(
        (failure) => expect(failure, isA<Validation>()),
        (_) => fail('expected Left'),
      );
    });

    test(
      'DioException with no response at all -> Left(NetworkOffline)',
      () async {
        final dioError = DioException(
          requestOptions: requestOptions,
          type: DioExceptionType.connectionError,
        );
        when(
          () => mockDio.post<Map<String, dynamic>>(
            any(),
            data: any(named: 'data'),
          ),
        ).thenThrow(dioError);

        final result = await apiClient.post('auth-signup', data: {'a': 1});

        expect(result.isLeft(), isTrue);
        result.match(
          (failure) => expect(failure, isA<NetworkOffline>()),
          (_) => fail('expected Left'),
        );
      },
    );

    test('a non-DioException thrown by dio -> Left(MalformedResponse), never '
        'a crash', () async {
      when(
        () =>
            mockDio.post<Map<String, dynamic>>(any(), data: any(named: 'data')),
      ).thenThrow(StateError('unexpected native failure'));

      final result = await apiClient.post('auth-signup', data: {'a': 1});

      expect(result.isLeft(), isTrue);
      result.match(
        (failure) => expect(failure, isA<MalformedResponse>()),
        (_) => fail('expected Left'),
      );
    });

    test('a null response body -> Left(MalformedResponse)', () async {
      final response = Response<Map<String, dynamic>>(
        requestOptions: requestOptions,
        statusCode: 200,
      );
      when(
        () =>
            mockDio.post<Map<String, dynamic>>(any(), data: any(named: 'data')),
      ).thenAnswer((_) async => response);

      final result = await apiClient.post('auth-signup', data: {'a': 1});

      expect(result.isLeft(), isTrue);
      result.match(
        (failure) => expect(failure, isA<MalformedResponse>()),
        (_) => fail('expected Left'),
      );
    });

    test('a client-side connect timeout maps to Left(NetworkTimeout), not '
        'NetworkOffline (patch item 1)', () async {
      final dioError = DioException(
        requestOptions: requestOptions,
        type: DioExceptionType.connectionTimeout,
      );
      when(
        () =>
            mockDio.post<Map<String, dynamic>>(any(), data: any(named: 'data')),
      ).thenThrow(dioError);

      final result = await apiClient.post('auth-signup', data: {'a': 1});

      expect(result.isLeft(), isTrue);
      result.match((failure) {
        expect(failure, isA<NetworkTimeout>());
        expect(failure.retryable, isTrue);
      }, (_) => fail('expected Left'));
    });

    test('a cancelled request maps to Left(MalformedResponse), never '
        'NetworkOffline — it must never be retried (patch item 2)', () async {
      final dioError = DioException(
        requestOptions: requestOptions,
        type: DioExceptionType.cancel,
      );
      when(
        () =>
            mockDio.post<Map<String, dynamic>>(any(), data: any(named: 'data')),
      ).thenThrow(dioError);

      final result = await apiClient.post('auth-signup', data: {'a': 1});

      expect(result.isLeft(), isTrue);
      result.match((failure) {
        expect(failure, isA<MalformedResponse>());
        expect(failure.retryable, isFalse);
      }, (_) => fail('expected Left'));
    });

    test(
      'get sends queryParameters through and maps a success response',
      () async {
        final response = Response<Map<String, dynamic>>(
          requestOptions: requestOptions,
          statusCode: 200,
          data: {'items': <dynamic>[]},
        );
        when(
          () => mockDio.get<Map<String, dynamic>>(
            any(),
            queryParameters: any(named: 'queryParameters'),
          ),
        ).thenAnswer((_) async => response);

        final result = await apiClient.get(
          'entries-list',
          queryParameters: {'cursor': 'abc'},
        );

        expect(result.isRight(), isTrue);
        final captured = verify(
          () => mockDio.get<Map<String, dynamic>>(
            captureAny(),
            queryParameters: captureAny(named: 'queryParameters'),
          ),
        ).captured;
        expect(captured[0], '$baseUrl/entries-list');
        expect(captured[1], {'cursor': 'abc'});
      },
    );

    test('patch sends data through and maps a success response', () async {
      final response = Response<Map<String, dynamic>>(
        requestOptions: requestOptions,
        statusCode: 200,
        data: {'updated': true},
      );
      when(
        () => mockDio.patch<Map<String, dynamic>>(
          any(),
          data: any(named: 'data'),
        ),
      ).thenAnswer((_) async => response);

      final result = await apiClient.patch(
        'account-settings-update',
        data: {'name': 'x'},
      );

      expect(result.isRight(), isTrue);
      result.match(
        (_) => fail('expected Right'),
        (data) => expect(data, {'updated': true}),
      );
    });

    test('delete maps errors the same way the other verbs do', () async {
      when(
        () => mockDio.delete<Map<String, dynamic>>(
          any(),
          data: any(named: 'data'),
        ),
      ).thenThrow(
        DioException(
          requestOptions: requestOptions,
          type: DioExceptionType.connectionError,
        ),
      );

      final result = await apiClient.delete('account');

      expect(result.isLeft(), isTrue);
      result.match(
        (failure) => expect(failure, isA<NetworkOffline>()),
        (_) => fail('expected Left'),
      );
    });
  });

  group(
    'Story 1.5 — mid-session AUTH_EXPIRED notifies SessionExpiryNotifier',
    () {
      test(
        'AUTH_EXPIRED on a bearer (non-anon-key) function notifies the expiry '
        'listener exactly once (AD-2/AD-5)',
        () async {
          final bearerRequestOptions = RequestOptions(
            path: '$baseUrl/entries-list',
          );
          final dioError = DioException(
            requestOptions: bearerRequestOptions,
            response: Response(
              requestOptions: bearerRequestOptions,
              statusCode: 401,
              data: {
                'code': 'AUTH_EXPIRED',
                'message': 'Session expired',
                'retryable': false,
              },
            ),
            type: DioExceptionType.badResponse,
          );
          when(
            () => mockDio.get<Map<String, dynamic>>(
              any(),
              queryParameters: any(named: 'queryParameters'),
            ),
          ).thenThrow(dioError);

          final result = await apiClient.get('entries-list');

          expect(result.isLeft(), isTrue);
          result.match(
            (failure) => expect(failure, isA<AuthExpired>()),
            (_) => fail('expected Left'),
          );
          verify(() => mockSessionExpiryNotifier.notifyExpired()).called(1);
        },
      );

      test('AUTH_EXPIRED on one of the three anon-key-only functions '
          '(auth-refresh) never notifies — Story 1.4\'s boot-time '
          'restoreSession() path stays untouched', () async {
        final refreshRequestOptions = RequestOptions(
          path: '$baseUrl/auth-refresh',
        );
        final dioError = DioException(
          requestOptions: refreshRequestOptions,
          response: Response(
            requestOptions: refreshRequestOptions,
            statusCode: 401,
            data: {
              'code': 'AUTH_EXPIRED',
              'message': 'Refresh token dead',
              'retryable': false,
            },
          ),
          type: DioExceptionType.badResponse,
        );
        when(
          () => mockDio.post<Map<String, dynamic>>(
            any(),
            data: any(named: 'data'),
          ),
        ).thenThrow(dioError);

        final result = await apiClient.post(
          'auth-refresh',
          data: {'refreshToken': 'stored-refresh-token'},
        );

        expect(result.isLeft(), isTrue);
        result.match(
          (failure) => expect(failure, isA<AuthExpired>()),
          (_) => fail('expected Left'),
        );
        verifyNever(() => mockSessionExpiryNotifier.notifyExpired());
      });

      test(
        'a non-AUTH_EXPIRED failure never notifies, even on a bearer function',
        () async {
          final bearerRequestOptions = RequestOptions(
            path: '$baseUrl/entries-create',
          );
          when(
            () => mockDio.post<Map<String, dynamic>>(
              any(),
              data: any(named: 'data'),
            ),
          ).thenThrow(
            DioException(
              requestOptions: bearerRequestOptions,
              type: DioExceptionType.connectionError,
            ),
          );

          final result = await apiClient.post('entries-create', data: {});

          expect(result.isLeft(), isTrue);
          result.match(
            (failure) => expect(failure, isA<NetworkOffline>()),
            (_) => fail('expected Left'),
          );
          verifyNever(() => mockSessionExpiryNotifier.notifyExpired());
        },
      );
    },
  );
}

import 'package:flutter_test/flutter_test.dart';
import 'package:fpdart/fpdart.dart';
import 'package:mocktail/mocktail.dart';

import 'package:cerne/core/failure/failure.dart';
import 'package:cerne/core/resource.dart';
import 'package:cerne/features/auth/domain/entities/authenticated_user.dart';
import 'package:cerne/features/auth/domain/repositories/auth_repository.dart';
import 'package:cerne/features/auth/domain/repositories/session_repository.dart';
import 'package:cerne/features/auth/presentation/cubit/auth_cubit.dart';
import 'package:cerne/features/auth/presentation/cubit/auth_state.dart';

class MockAuthRepository extends Mock implements AuthRepository {}

class MockSessionRepository extends Mock implements SessionRepository {}

/// Collects every state the cubit emits for the duration of [act], since the
/// stack has no `bloc_test` pin — this drives [AuthCubit] through its public
/// API only (never the `@protected` `emit`), the same way any other
/// `flutter_bloc` consumer would.
Future<List<AuthState>> _emittedDuring(
  AuthCubit cubit,
  Future<void> Function() act,
) async {
  final emitted = <AuthState>[];
  final subscription = cubit.stream.listen(emitted.add);
  await act();
  // `submit()`'s awaited repository call resolves its mocked Future on a
  // microtask; `Future.delayed(Duration.zero)` only resumes once the whole
  // microtask queue (including the stream's event dispatch to our
  // listener) has drained, so this reliably waits for every emit `act()`
  // triggered before we stop listening.
  await Future<void>.delayed(Duration.zero);
  await subscription.cancel();
  return emitted;
}

void main() {
  late MockAuthRepository mockAuthRepository;
  late MockSessionRepository mockSessionRepository;

  setUp(() {
    mockAuthRepository = MockAuthRepository();
    mockSessionRepository = MockSessionRepository();
    when(() => mockSessionRepository.markAuthenticated()).thenReturn(null);
  });

  group('AuthCubit — mode toggle', () {
    test(
      'toggleMode flips login <-> signUp, keeping typed field values',
      () async {
        final cubit = AuthCubit(mockAuthRepository, mockSessionRepository);
        cubit.emailChanged('a@b.com');
        cubit.passwordChanged('segredo');

        final emitted = await _emittedDuring(
          cubit,
          () async => cubit.toggleMode(),
        );

        expect(emitted, [
          const AuthState(
            mode: AuthMode.signUp,
            email: 'a@b.com',
            password: 'segredo',
          ),
        ]);
        await cubit.close();
      },
    );
  });

  group('AuthCubit — local validation blocks submit', () {
    test(
      'a malformed email blocks submit before any repository call',
      () async {
        final cubit = AuthCubit(mockAuthRepository, mockSessionRepository);
        cubit.emailChanged('nao-e-email');
        cubit.passwordChanged('segredo');

        final emitted = await _emittedDuring(cubit, cubit.submit);

        expect(emitted, [
          const AuthState(
            email: 'nao-e-email',
            password: 'segredo',
            emailError: 'E-mail inválido',
          ),
        ]);
        verifyNever(
          () => mockAuthRepository.logIn(
            email: any(named: 'email'),
            password: any(named: 'password'),
          ),
        );
        verifyNever(
          () => mockAuthRepository.signUp(
            email: any(named: 'email'),
            password: any(named: 'password'),
          ),
        );
        await cubit.close();
      },
    );

    test(
      'an empty password blocks submit before any repository call',
      () async {
        final cubit = AuthCubit(mockAuthRepository, mockSessionRepository);
        cubit.emailChanged('a@b.com');

        final emitted = await _emittedDuring(cubit, cubit.submit);

        expect(emitted, [
          const AuthState(email: 'a@b.com', passwordError: 'Senha obrigatória'),
        ]);
        verifyNever(
          () => mockAuthRepository.logIn(
            email: any(named: 'email'),
            password: any(named: 'password'),
          ),
        );
        await cubit.close();
      },
    );

    test('passwordChanged clears a pre-existing emailError, symmetric with '
        'emailChanged', () async {
      final cubit = AuthCubit(mockAuthRepository, mockSessionRepository);
      cubit.emailChanged('nao-e-email');
      cubit.passwordChanged('segredo');
      // Drives emailError non-null via a real failed-validation submit,
      // not by poking state directly.
      await cubit.submit();
      expect(cubit.state.emailError, 'E-mail inválido');

      final emitted = await _emittedDuring(
        cubit,
        () async => cubit.passwordChanged('nova-senha'),
      );

      expect(emitted, [
        const AuthState(email: 'nao-e-email', password: 'nova-senha'),
      ]);
      await cubit.close();
    });
  });

  group('AuthCubit — successful submit', () {
    test('login success emits loading then ResourceData, calling auth-login '
        'with exactly the typed email/password', () async {
      when(
        () => mockAuthRepository.logIn(
          email: any(named: 'email'),
          password: any(named: 'password'),
        ),
      ).thenAnswer(
        (_) async => right(const AuthenticatedUser(id: 'u1', email: 'a@b.com')),
      );
      final cubit = AuthCubit(mockAuthRepository, mockSessionRepository);
      cubit.emailChanged('a@b.com');
      cubit.passwordChanged('segredo123');

      final emitted = await _emittedDuring(cubit, cubit.submit);

      expect(emitted, [
        const AuthState(
          email: 'a@b.com',
          password: 'segredo123',
          status: ResourceLoading<Unit>(),
        ),
        // password is cleared once it's done its job — it's no longer
        // needed in memory after a successful auth call (code review of
        // story-1-3-account-creation-and-login).
        const AuthState(email: 'a@b.com', status: ResourceData<Unit>(unit)),
      ]);
      verify(
        () =>
            mockAuthRepository.logIn(email: 'a@b.com', password: 'segredo123'),
      ).called(1);
      // Story 1.6 boundary — called before the `ResourceData` emission
      // above, so the router's redirect already sees `authenticated` by
      // the time a listener reacts to that emission.
      verify(() => mockSessionRepository.markAuthenticated()).called(1);
      await cubit.close();
    });

    test('signup mode calls signUp, not logIn', () async {
      when(
        () => mockAuthRepository.signUp(
          email: any(named: 'email'),
          password: any(named: 'password'),
        ),
      ).thenAnswer(
        (_) async =>
            right(const AuthenticatedUser(id: 'u2', email: 'nova@b.com')),
      );
      final cubit = AuthCubit(mockAuthRepository, mockSessionRepository);
      cubit.toggleMode();
      cubit.emailChanged('nova@b.com');
      cubit.passwordChanged('segredo123');

      await cubit.submit();

      verify(
        () => mockAuthRepository.signUp(
          email: 'nova@b.com',
          password: 'segredo123',
        ),
      ).called(1);
      verifyNever(
        () => mockAuthRepository.logIn(
          email: any(named: 'email'),
          password: any(named: 'password'),
        ),
      );
      await cubit.close();
    });

    test('leading/trailing whitespace in the typed e-mail is trimmed before '
        'it reaches the repository', () async {
      when(
        () => mockAuthRepository.logIn(
          email: any(named: 'email'),
          password: any(named: 'password'),
        ),
      ).thenAnswer(
        (_) async => right(const AuthenticatedUser(id: 'u1', email: 'a@b.com')),
      );
      final cubit = AuthCubit(mockAuthRepository, mockSessionRepository);
      cubit.emailChanged('  a@b.com  ');
      cubit.passwordChanged('segredo123');

      await cubit.submit();

      verify(
        () =>
            mockAuthRepository.logIn(email: 'a@b.com', password: 'segredo123'),
      ).called(1);
      await cubit.close();
    });
  });

  group('AuthCubit — AUTH_INVALID', () {
    test('AUTH_INVALID keeps the typed values and surfaces the message '
        'once, via formError', () async {
      when(
        () => mockAuthRepository.logIn(
          email: any(named: 'email'),
          password: any(named: 'password'),
        ),
      ).thenAnswer(
        (_) async =>
            left(const Failure.authInvalid(message: 'Credenciais inválidas')),
      );
      final cubit = AuthCubit(mockAuthRepository, mockSessionRepository);
      cubit.emailChanged('a@b.com');
      cubit.passwordChanged('errada');

      final emitted = await _emittedDuring(cubit, cubit.submit);

      expect(emitted, [
        const AuthState(
          email: 'a@b.com',
          password: 'errada',
          status: ResourceLoading<Unit>(),
        ),
        const AuthState(
          email: 'a@b.com',
          password: 'errada',
          formError: 'Credenciais inválidas',
        ),
      ]);
      verifyNever(() => mockSessionRepository.markAuthenticated());
      await cubit.close();
    });
  });
}

import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:fpdart/fpdart.dart' hide State;

import '../../../../core/design_tokens.dart';
import '../../../../core/resource.dart';
import '../../../../core/widgets/app_button.dart';
import '../../../../core/widgets/app_text_field.dart';
import '../cubit/auth_cubit.dart';
import '../cubit/auth_state.dart';

/// Tela 0.1a (prototype-extract.md §4): "Entrar"/"Criar conta", two
/// `AppTextField`s + one `AppButton` + a ghost toggle link — unchanged
/// shared primitives, no new params. No "usar biometria" link (Epic 2's
/// vault isn't built — omitted rather than shipped dead); no
/// `SessionStatus`/`go_router` (Story 1.4/1.6 scope): [onAuthenticated] is
/// how the caller (`main.dart`) decides what comes after success.
class AuthScreen extends StatelessWidget {
  const AuthScreen({
    super.key,
    required this.cubit,
    required this.onAuthenticated,
  });

  final AuthCubit cubit;

  /// Called once, the first time `state.status` becomes `ResourceData`
  /// (i.e. the access token has already been persisted — the repository
  /// saves it before resolving).
  final void Function(BuildContext context) onAuthenticated;

  @override
  Widget build(BuildContext context) {
    return BlocProvider.value(
      value: cubit,
      child: BlocListener<AuthCubit, AuthState>(
        listenWhen: (previous, current) =>
            current.status is ResourceData<Unit> &&
            previous.status is! ResourceData<Unit>,
        listener: (context, state) => onAuthenticated(context),
        child: const _AuthView(),
      ),
    );
  }
}

class _AuthView extends StatefulWidget {
  const _AuthView();

  @override
  State<_AuthView> createState() => _AuthViewState();
}

class _AuthViewState extends State<_AuthView> {
  final _emailController = TextEditingController();
  final _passwordController = TextEditingController();
  final _passwordFocus = FocusNode();

  @override
  void dispose() {
    _emailController.dispose();
    _passwordController.dispose();
    _passwordFocus.dispose();
    super.dispose();
  }

  // Keeps the (locally-owned) text controllers in sync with the cubit's
  // state without fighting the user's caret position — only written when
  // the value actually diverges (e.g. on `toggleMode`, which doesn't touch
  // field values, this is a no-op). On `AUTH_INVALID`/network failure the
  // cubit state's `email`/`password` are untouched, so this keeps the
  // user's typed values exactly as they were (epics.md Story 1.3 AC).
  void _syncControllers(AuthState state) {
    if (_emailController.text != state.email) {
      _emailController.value = _emailController.value.copyWith(
        text: state.email,
        selection: TextSelection.collapsed(offset: state.email.length),
      );
    }
    if (_passwordController.text != state.password) {
      _passwordController.value = _passwordController.value.copyWith(
        text: state.password,
        selection: TextSelection.collapsed(offset: state.password.length),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: DesignTokens.colorSurfaceBg,
      body: SafeArea(
        child: BlocBuilder<AuthCubit, AuthState>(
          builder: (context, state) {
            _syncControllers(state);

            final cubit = context.read<AuthCubit>();
            final isLogin = state.mode == AuthMode.login;
            final isSubmitting = state.isSubmitting;

            // Both fields get the error border on a form-level failure
            // (AUTH_INVALID/network); the message itself is shown once,
            // under senha. `errorText: ''` on e-mail is border-only
            // (app_text_field.dart's documented convention). A local,
            // password-only validation error (`passwordError`, "Senha
            // obrigatória") is single-field — the e-mail value already
            // passed its own check, so it must never be bordered for it.
            final emailErrorText =
                state.emailError ?? (state.formError != null ? '' : null);
            final passwordErrorText = state.formError ?? state.passwordError;

            return SingleChildScrollView(
              padding: DesignTokens.screenPadding,
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                mainAxisSize: MainAxisSize.min,
                children: [
                  const SizedBox(height: DesignTokens.spacing2xl),
                  Text(
                    isLogin ? 'Bem-vindo de volta' : 'Crie sua conta',
                    textAlign: TextAlign.center,
                    style: DesignTokens.textHeadlineMd.copyWith(
                      color: DesignTokens.colorTextPrimary,
                    ),
                  ),
                  const SizedBox(height: DesignTokens.spacingLg),
                  AppTextField(
                    controller: _emailController,
                    labelText: 'E-mail',
                    keyboardType: TextInputType.emailAddress,
                    textInputAction: TextInputAction.next,
                    errorText: emailErrorText,
                    onChanged: cubit.emailChanged,
                  ),
                  const SizedBox(height: DesignTokens.spacingMd),
                  AppTextField(
                    controller: _passwordController,
                    focusNode: _passwordFocus,
                    labelText: 'Senha',
                    obscureText: true,
                    textInputAction: TextInputAction.done,
                    errorText: passwordErrorText,
                    onChanged: cubit.passwordChanged,
                  ),
                  const SizedBox(height: DesignTokens.spacingLg),
                  AppButton(
                    label: isSubmitting
                        ? (isLogin ? 'Entrando…' : 'Criando conta…')
                        : (isLogin ? 'Entrar' : 'Criar conta'),
                    onPressed: isSubmitting ? null : cubit.submit,
                  ),
                  const SizedBox(height: DesignTokens.spacingMd),
                  AppButton(
                    variant: AppButtonVariant.textGhost,
                    label: isLogin
                        ? 'Não tem conta? Criar conta'
                        : 'Já tem conta? Entrar',
                    onPressed: isSubmitting ? null : cubit.toggleMode,
                  ),
                ],
              ),
            );
          },
        ),
      ),
    );
  }
}

