/// Every other network test (`api_client_test.dart`, `header_interceptor_test.dart`,
/// `retry_interceptor_test.dart`) mocks `Dio` itself or drives one interceptor
/// in isolation — neither proves the pieces work *wired together* the way
/// `setupCoreDependencies` actually wires them (AD-5), nor that a retry
/// genuinely goes back out over the wire.
///
/// Like `bootstrap_integration_test.dart` fakes the native secure-storage
/// channel (no device/CI exists yet to do otherwise), this fakes only the
/// transport boundary (`HttpClientAdapter`) — everything above it (URL
/// building, both real interceptors, `ApiClient`'s mapping) is the genuine
/// production wiring.
class _FakeHttpClientAdapter implements HttpClientAdapter {
  final List<RequestOptions> requests = [];
  final List<({int statusCode, Map<String, dynamic> body})> _queue = [];

  void queueJsonResponse(int statusCode, Map<String, dynamic> body) {
    _queue.add((statusCode: statusCode, body: body));
  }

  @override
  Future<ResponseBody> fetch(
    RequestOptions options,
    Stream<Uint8List>? requestStream,
    Future<void>? cancelFuture,
  ) async {
    requests.add(options);
    if (_queue.isEmpty) {
      throw StateError(
        'No queued response for ${options.method} ${options.path}',
      );
    }
    final next = _queue.removeAt(0);
    return ResponseBody.fromString(
      jsonEncode(next.body),
      next.statusCode,
      headers: {
        Headers.contentTypeHeader: [Headers.jsonContentType],
      },
    );
  }

  @override
  void close({bool force = false}) {}
}

/// A minimal, real (non-mocked) in-memory implementation — this suite is
/// about proving the wiring, not re-verifying token-storage behavior
/// (already covered by `access_token_provider_test.dart`).
class _InMemoryAccessTokenProvider implements AccessTokenProvider {
  String? _token;
  String? _refreshToken;

  @override
  Future<String?> readAccessToken() async => _token;

  @override
  Future<void> saveAccessToken(String token) async => _token = token;

  @override
  Future<void> clearAccessToken() async => _token = null;

  @override
  Future<String?> readRefreshToken() async => _refreshToken;

  @override
  Future<void> saveSession({
    required String accessToken,
    required String refreshToken,
  }) async {
    _token = accessToken;
    _refreshToken = refreshToken;
  }

  @override
  Future<void> clearSession() async {
    _token = null;
    _refreshToken = null;
  }
}

void main() {
  const baseUrl = 'https://host.example.com';
  const anonKey = 'anon-key-value';

  late _FakeHttpClientAdapter adapter;
  late _InMemoryAccessTokenProvider tokenProvider;
  late SessionExpiryNotifierImpl sessionExpiryNotifier;
  late ApiClient apiClient;

  setUp(() {
    adapter = _FakeHttpClientAdapter();
    tokenProvider = _InMemoryAccessTokenProvider();
    sessionExpiryNotifier = SessionExpiryNotifierImpl();

    // Mirrors `setupCoreDependencies`'s wiring exactly: real Dio, both real
    // interceptors attached in the same order, header interceptor fed the
    // same anon key + token provider contract.
    final dio = Dio(BaseOptions())..httpClientAdapter = adapter;
    dio.interceptors.add(
      HeaderInterceptor(anonKey: anonKey, accessTokenProvider: tokenProvider),
    );
    dio.interceptors.add(RetryInterceptor(dio));

    apiClient = ApiClient(
      dio: dio,
      urlBuilder: const UrlBuilder(baseUrl),
      sessionExpiryNotifier: sessionExpiryNotifier,
    );
  });

  group('network pipeline — real Dio + real interceptors, faked transport', () {
    test('an anon-only operation (auth-login) goes out at the x-cerne-function '
        'URL with apikey + anon Authorization, and the success body maps to '
        'Right', () async {
      adapter.queueJsonResponse(200, {'accessToken': 'tok-1'});

      final result = await apiClient.post(
        'auth-login',
        data: {'email': 'a@b.com', 'password': 'secret'},
      );

      expect(result.isRight(), isTrue);
      result.match(
        (_) => fail('expected Right'),
        (data) => expect(data, {'accessToken': 'tok-1'}),
      );

      expect(adapter.requests, hasLength(1));
      final sent = adapter.requests.single;
      expect(sent.path, '$baseUrl/auth-login');
      expect(sent.headers['apikey'], anonKey);
      expect(sent.headers['Authorization'], 'Bearer $anonKey');
    });

    test('auth-refresh goes out with the anon-key bearer even when a '
        '(possibly dead) user access token is already stored — refresh must '
        'never need it (Story 1.4)', () async {
      await tokenProvider.saveAccessToken('stale-access-token');
      adapter.queueJsonResponse(200, {
        'session': {
          'accessToken': 'new-access-token',
          'refreshToken': 'new-refresh-token',
          'expiresIn': 3600,
          'expiresAt': 1999999999,
          'tokenType': 'bearer',
        },
      });

      final result = await apiClient.post(
        'auth-refresh',
        data: {'refreshToken': 'stored-refresh-token'},
      );

      expect(result.isRight(), isTrue);
      final sent = adapter.requests.single;
      expect(sent.path, '$baseUrl/auth-refresh');
      expect(sent.headers['apikey'], anonKey);
      expect(sent.headers['Authorization'], 'Bearer $anonKey');
    });

    test('a bearer operation with a stored user token sends that token, not '
        'the anon key — and trailing path params are appended as real URL '
        'segments, never the literal openapi.yaml path (AD-5)', () async {
      await tokenProvider.saveAccessToken('user-token-1');
      adapter.queueJsonResponse(200, {'id': 'message-1', 'status': 'queued'});

      final result = await apiClient.post(
        'chat-messages-retry',
        pathParams: ['session-1', 'message-1'],
      );

      expect(result.isRight(), isTrue);
      final sent = adapter.requests.single;
      expect(sent.path, '$baseUrl/chat-messages-retry/session-1/message-1');
      expect(sent.headers['apikey'], anonKey);
      expect(sent.headers['Authorization'], 'Bearer user-token-1');
    });

    test('a retryable server error (RATE_LIMITED) is genuinely retried over '
        'the wire and the eventual success maps to Right', () async {
      adapter.queueJsonResponse(429, {
        'code': 'RATE_LIMITED',
        'message': 'slow down',
        'retryable': true,
      });
      adapter.queueJsonResponse(200, {'items': <dynamic>[]});

      final result = await apiClient.get('entries-list');

      expect(result.isRight(), isTrue);
      result.match(
        (_) => fail('expected Right'),
        (data) => expect(data, {'items': <dynamic>[]}),
      );
      // Two real requests actually left through the adapter: the retry
      // policy (AD-4) isn't just deciding to retry, it's re-driving the
      // same Dio pipeline end to end.
      expect(adapter.requests, hasLength(2));
    });

    test('a retryable error that never recovers is retried exactly '
        'maxRetries times and then surfaces as the matching Left', () async {
      for (var i = 0; i <= RetryInterceptor.maxRetries; i++) {
        adapter.queueJsonResponse(504, {
          'code': 'NETWORK_TIMEOUT',
          'message': 'gateway timeout',
          'retryable': true,
        });
      }

      final result = await apiClient.get('entries-list');

      expect(result.isLeft(), isTrue);
      result.match((failure) {
        expect(failure, isA<NetworkTimeout>());
        expect(failure.retryable, isTrue);
      }, (_) => fail('expected Left'));
      // Initial attempt + maxRetries retries, all real requests.
      expect(adapter.requests, hasLength(1 + RetryInterceptor.maxRetries));
    });

    test('a non-retryable error (AUTH_INVALID) surfaces immediately as the '
        'matching Left, with no retry request ever sent', () async {
      adapter.queueJsonResponse(401, {
        'code': 'AUTH_INVALID',
        'message': 'bad credentials',
        'retryable': false,
      });

      final result = await apiClient.post(
        'auth-login',
        data: {'email': 'a@b.com', 'password': 'wrong'},
      );

      expect(result.isLeft(), isTrue);
      result.match((failure) {
        expect(failure, isA<AuthInvalid>());
        expect(failure.retryable, isFalse);
      }, (_) => fail('expected Left'));
      expect(adapter.requests, hasLength(1));
    });

    test(
      'Story 1.5: a mid-session AUTH_EXPIRED on a bearer endpoint fires the '
      "real SessionExpiryNotifier's expiredEvents through the whole real "
      'pipeline, while the same code on auth-refresh never does',
      () async {
        final events = <void>[];
        final subscription = sessionExpiryNotifier.expiredEvents.listen(
          events.add,
        );
        addTearDown(subscription.cancel);

        adapter.queueJsonResponse(401, {
          'code': 'AUTH_EXPIRED',
          'message': 'Session expired',
          'retryable': false,
        });
        await apiClient.get('entries-list');
        await Future<void>.delayed(Duration.zero);
        expect(events, hasLength(1));

        adapter.queueJsonResponse(401, {
          'code': 'AUTH_EXPIRED',
          'message': 'Refresh token dead',
          'retryable': false,
        });
        await apiClient.post(
          'auth-refresh',
          data: {'refreshToken': 'dead-token'},
        );
        await Future<void>.delayed(Duration.zero);
        expect(events, hasLength(1));
      },
    );
  });
}

import 'package:flutter/material.dart';

import '../design_tokens.dart';
import 'app_button.dart';

/// Shared confirmation-dialog overlay (prototype-extract.md §6: "scrim +
/// centered card; neutral title (session) or red title (destructive
/// deletion)"). Story 1.5 is the first consumer (neutral `colorTextPrimary`
/// title, the session-expiry recovery copy); a later story (Epic 8's
/// account-deletion confirm) reuses this same widget with [titleColor]
/// set to `DesignTokens.colorError` and a heavier [barrierColor].
///
/// UX-DR16/25/27/36: non-dismissible barrier, focus trapped on the dialog,
/// `scrimIn` (0.18s ease-out fade) as the only entrance choreography, and
/// at most one instance open at a time — [show] is the one way this
/// widget is ever presented, and owns that single-overlay guard itself so
/// no caller has to re-implement it.
class ConfirmationDialog extends StatelessWidget {
  const ConfirmationDialog({
    super.key,
    required this.icon,
    required this.title,
    required this.message,
    required this.confirmLabel,
    required this.onConfirm,
    required this.barrierColor,
    this.titleColor = DesignTokens.colorTextPrimary,
    this.caption,
  });

  final IconData icon;
  final String title;
  final String message;
  final String confirmLabel;
  final VoidCallback onConfirm;

  /// The full-bleed scrim color behind the centered card — callers pass
  /// `DesignTokens.colorScrim` (session-expiry, Story 1.5) or the heavier
  /// drawer/sheet value a later story uses for its own confirmation.
  final Color barrierColor;

  /// Neutral (`colorTextPrimary`, the default — Story 1.5's session copy)
  /// or destructive (`colorError`, a later story's account-deletion
  /// confirm) — never any other color (Boundaries: "neutral
  /// `colorTextPrimary` title, never `colorError`" for *this* story's own
  /// call site).
  final Color titleColor;

  /// Small mono caption below the button (Story 1.5: "o histórico e a
  /// posição do scroll são preservados"). Optional — a future destructive
  /// confirmation has no equivalent.
  final String? caption;

  /// Whether an instance is currently showing — the single-overlay guard
  /// (UX-DR16/25/27/36: "never stacks on another open overlay"). Exposed
  /// for tests; callers should not need to read it directly.
  static bool isOpen = false;

  /// Presents [builder]'s [ConfirmationDialog] as a non-dismissible,
  /// focus-trapped overlay above whatever screen is currently showing,
  /// without replacing it — the underlying route stays mounted, so its
  /// scroll/state is preserved (Boundaries: "the authenticated screen's
  /// widget instance is never replaced").
  ///
  /// A second call while one is already open is a silent no-op (I/O
  /// matrix: "already-open overlay ... no second dialog stacks").
  static Future<void> show({
    required BuildContext context,
    required WidgetBuilder builder,
  }) {
    if (isOpen) {
      return Future<void>.value();
    }
    isOpen = true;
    try {
      return showGeneralDialog<void>(
        context: context,
        barrierDismissible: false,
        // The framework's own `ModalBarrier` stays fully transparent — the
        // scrim actually seen on screen is this widget's own `build()`
        // below, which lets `transitionBuilder` fade the scrim and the card
        // together as one `scrimIn` choreography instead of two separately
        // animated layers.
        barrierColor: Colors.transparent,
        transitionDuration: const Duration(milliseconds: 180),
        transitionBuilder: (context, animation, secondaryAnimation, child) {
          return FadeTransition(
            opacity: CurvedAnimation(
              parent: animation,
              curve: Curves.easeOut,
            ),
            child: child,
          );
        },
        pageBuilder: (context, animation, secondaryAnimation) => PopScope(
          // UX-DR16/25/27/36 — non-dismissible: `barrierDismissible: false`
          // above only stops a scrim tap; without this, the system/hardware
          // back gesture would still pop the route and close the overlay.
          canPop: false,
          child: builder(context),
        ),
      ).whenComplete(() => isOpen = false);
    } catch (_) {
      // A synchronous throw from `showGeneralDialog` (e.g. a future caller
      // passing a `context` with no `Navigator` ancestor) must still release
      // the guard — otherwise every later `show()` call, from any caller,
      // silently no-ops forever.
      isOpen = false;
      rethrow;
    }
  }

  @override
  Widget build(BuildContext context) {
    return Stack(
      fit: StackFit.expand,
      children: [
        ColoredBox(color: barrierColor),
        // `LayoutBuilder` + `ConstrainedBox(minHeight: ...)` is the
        // standard "centered, but scrollable if it doesn't fit" shape:
        // ordinary-scale content still centers vertically exactly as
        // before (the min-height constraint is satisfied with room to
        // spare, so `Center` centers within it), but under an extreme
        // Dynamic Type scale — where the card's intrinsic height can
        // exceed the screen — this scrolls instead of overflowing
        // (RNF08's "no control truncates under Dynamic Type").
        LayoutBuilder(
          builder: (context, constraints) => SingleChildScrollView(
            child: ConstrainedBox(
              constraints: BoxConstraints(minHeight: constraints.maxHeight),
              child: Center(
                child: Padding(
                  padding: DesignTokens.dialogScreenMargin,
                  child: _Card(
                    icon: icon,
                    title: title,
                    titleColor: titleColor,
                    message: message,
                    confirmLabel: confirmLabel,
                    onConfirm: onConfirm,
                    caption: caption,
                  ),
                ),
              ),
            ),
          ),
        ),
      ],
    );
  }
}

class _Card extends StatelessWidget {
  const _Card({
    required this.icon,
    required this.title,
    required this.titleColor,
    required this.message,
    required this.confirmLabel,
    required this.onConfirm,
    required this.caption,
  });

  final IconData icon;
  final String title;
  final Color titleColor;
  final String message;
  final String confirmLabel;
  final VoidCallback onConfirm;
  final String? caption;

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: DesignTokens.dialogCardPadding,
      decoration: const BoxDecoration(
        color: DesignTokens.colorSurfaceElevated,
        borderRadius: BorderRadius.all(Radius.circular(DesignTokens.radiusLg)),
        boxShadow: DesignTokens.elevation2,
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Row(
            children: [
              Icon(
                icon,
                size: DesignTokens.dialogIconSize,
                color: DesignTokens.colorPrimary,
              ),
              const SizedBox(width: DesignTokens.spacingSm),
              Expanded(
                child: Text(
                  title,
                  style: DesignTokens.textTitleSm.copyWith(color: titleColor),
                ),
              ),
            ],
          ),
          const SizedBox(height: DesignTokens.dialogContentGap),
          Text(
            message,
            style: DesignTokens.textBodyMd.copyWith(
              color: DesignTokens.colorTextSecondary,
            ),
          ),
          const SizedBox(height: DesignTokens.dialogContentGap),
          AppButton(label: confirmLabel, onPressed: onConfirm),
          if (caption != null) ...[
            const SizedBox(height: DesignTokens.dialogContentGap),
            Text(
              caption!,
              textAlign: TextAlign.center,
              style: DesignTokens.textMonoCaption.copyWith(
                color: DesignTokens.colorTextSecondary,
              ),
            ),
          ],
        ],
      ),
    );
  }
}

