import 'package:flutter/services.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';
import 'package:flutter_test/flutter_test.dart';

import 'package:cerne/core/network/access_token_provider.dart';

/// `SecureStorageAccessTokenProvider` itself (as opposed to the raw
/// `FlutterSecureStorage` instance) was previously only exercised
/// indirectly — this proves save/read/clear on the provider's own API,
/// the same native-channel-faking approach as
/// `bootstrap_integration_test.dart`.
void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  const secureStorageChannel = MethodChannel(
    'plugins.it_nomads.com/flutter_secure_storage',
  );
  final fakeNativeStorage = <String, String>{};

  Future<dynamic> handleSecureStorageCall(MethodCall call) async {
    final args = call.arguments as Map<dynamic, dynamic>;
    switch (call.method) {
      case 'write':
        fakeNativeStorage[args['key'] as String] = args['value'] as String;
        return null;
      case 'read':
        return fakeNativeStorage[args['key'] as String];
      case 'delete':
        fakeNativeStorage.remove(args['key'] as String);
        return null;
      case 'containsKey':
        return fakeNativeStorage.containsKey(args['key'] as String);
      default:
        return null;
    }
  }

  late SecureStorageAccessTokenProvider provider;

  setUp(() {
    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
        .setMockMethodCallHandler(
          secureStorageChannel,
          handleSecureStorageCall,
        );
    fakeNativeStorage.clear();
    provider = SecureStorageAccessTokenProvider(const FlutterSecureStorage());
  });

  tearDown(() {
    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
        .setMockMethodCallHandler(secureStorageChannel, null);
  });

  group('SecureStorageAccessTokenProvider', () {
    test('readAccessToken returns null when nothing is stored', () async {
      expect(await provider.readAccessToken(), isNull);
    });

    test(
      'saveAccessToken then readAccessToken round-trips the token',
      () async {
        await provider.saveAccessToken('token-123');

        expect(await provider.readAccessToken(), 'token-123');
      },
    );

    test('clearAccessToken removes the stored token', () async {
      await provider.saveAccessToken('token-123');
      await provider.clearAccessToken();

      expect(await provider.readAccessToken(), isNull);
    });

    test('readRefreshToken returns null when nothing is stored', () async {
      expect(await provider.readRefreshToken(), isNull);
    });

    test('saveSession persists both halves of the pair, independently of '
        'readAccessToken/readRefreshToken', () async {
      await provider.saveSession(
        accessToken: 'access-123',
        refreshToken: 'refresh-456',
      );

      expect(await provider.readAccessToken(), 'access-123');
      expect(await provider.readRefreshToken(), 'refresh-456');
    });

    test(
      'a later saveSession overwrites both tokens of an earlier one',
      () async {
        await provider.saveSession(
          accessToken: 'access-1',
          refreshToken: 'refresh-1',
        );
        await provider.saveSession(
          accessToken: 'access-2',
          refreshToken: 'refresh-2',
        );

        expect(await provider.readAccessToken(), 'access-2');
        expect(await provider.readRefreshToken(), 'refresh-2');
      },
    );

    test('clearSession removes both the access and refresh tokens', () async {
      await provider.saveSession(
        accessToken: 'access-123',
        refreshToken: 'refresh-456',
      );
      await provider.clearSession();

      expect(await provider.readAccessToken(), isNull);
      expect(await provider.readRefreshToken(), isNull);
    });
  });
}

import 'package:dio/dio.dart';

/// AD-4/AD-5 — the one place a `DioException` is mapped to the backend's
/// error `code` (`error-taxonomy.md`), shared by `ApiClient` (which turns it
/// into a `Failure`) and `RetryInterceptor` (which decides whether to
/// retry). Previously reimplemented independently in both files, which let
/// a client-side timeout and a cancelled request both be misread as
/// `NETWORK_OFFLINE`.
///
/// Returns `null` when no code can be determined: a cancelled request
/// (`DioExceptionType.cancel`) or an HTTP response that doesn't carry the
/// expected `{code, message, retryable}` body. Neither is retryable, and
/// both end up mapped to `Failure.malformedResponse` by the caller.
String? dioErrorCodeOf(DioException e) {
  final data = e.response?.data;
  if (data is Map && data['code'] is String) {
    return data['code'] as String;
  }
  switch (e.type) {
    case DioExceptionType.connectionTimeout:
    case DioExceptionType.sendTimeout:
    case DioExceptionType.receiveTimeout:
      return 'NETWORK_TIMEOUT';
    case DioExceptionType.cancel:
      return null;
    default:
      break;
  }
  if (e.response == null) {
    return 'NETWORK_OFFLINE';
  }
  return null;
}

import 'package:flutter_test/flutter_test.dart';

import 'package:cerne/core/session/session_expiry_notifier.dart';

void main() {
  late SessionExpiryNotifierImpl notifier;

  setUp(() {
    notifier = SessionExpiryNotifierImpl();
  });

  group('SessionExpiryNotifierImpl', () {
    test('notifyExpired delivers one event to a listener', () async {
      final events = <void>[];
      final subscription = notifier.expiredEvents.listen(events.add);

      notifier.notifyExpired();
      await Future<void>.delayed(Duration.zero);

      expect(events, hasLength(1));
      await subscription.cancel();
    });

    test('expiredEvents is a broadcast stream — more than one listener can '
        'subscribe at once', () async {
      final firstEvents = <void>[];
      final secondEvents = <void>[];
      final firstSubscription = notifier.expiredEvents.listen(
        firstEvents.add,
      );
      final secondSubscription = notifier.expiredEvents.listen(
        secondEvents.add,
      );

      notifier.notifyExpired();
      await Future<void>.delayed(Duration.zero);

      expect(firstEvents, hasLength(1));
      expect(secondEvents, hasLength(1));
      await firstSubscription.cancel();
      await secondSubscription.cancel();
    });

    test('notifyExpired with no listener never throws', () {
      expect(notifier.notifyExpired, returnsNormally);
    });

    test('notifyExpired after dispose() is a silent no-op, never throws', () async {
      await notifier.dispose();

      expect(notifier.notifyExpired, returnsNormally);
    });

    test('dispose() closes the stream — a late listen gets no more events', () async {
      await notifier.dispose();

      final events = <void>[];
      final subscription = notifier.expiredEvents.listen(
        events.add,
        onDone: () {},
      );
      await Future<void>.delayed(Duration.zero);

      expect(events, isEmpty);
      await subscription.cancel();
    });
  });
}
